BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-k-q28', '8. AIに必要な数理・統計知識',
   '集合Aと集合Bがあるとき、AとBの両方に共通して入っている要素だけを集めたものを表す記号として正しいものはどれか。',
   NULL::text,
   '["∩（積集合の記号）。AとBの両方に入っている要素だけを集めたもの", "∪（和集合の記号）。AとBのどちらか一方にでも入っている要素をすべて集めたもの", "⊂（部分集合の記号）。ある集合がもう一つの集合にすっぽり含まれているかどうかを表すもの", "∈（要素であることを表す記号）。あるものが、ある集合に含まれているかどうかを表すもの"]',
   0, '[0]', 'single',
   '{"asked": "集合の「積集合（共通部分）」を表す記号を選ぶ問題。", "why_asked": "AIの数式では、データの集まりや条件を絞り込む場面で集合の記号が使われる。「共通するものだけ」と「どちらかにあるものすべて」を記号で区別できるかを問う基礎問題。", "kid": "集合とは「ものの集まり」のこと。例えば集合Aが「赤いもの」の集まり、集合Bが「丸いもの」の集まりだとすると、「赤くて丸いもの」だけを集めたものがAとBの積集合。この「両方に共通して入っている部分だけ」を表す記号が∩（キャップ、と読む）。", "eg": "たとえるなら、クラスの中で「野球部に入っている人」の集合と「サッカー部に入っている人」の集合があったとき、両方に入っている人（掛け持ちしている人）だけを集めたのが積集合。どちらかの部活に入っている人全員を集めたら、それは和集合になる。", "terms": [["集合", "ものの集まりのこと。例えば「1〜10の偶数の集まり」のように、何かの条件を満たすものをひとまとめにしたもの"], ["∩（キャップ）", "積集合（共通部分）を表す記号。AとBの両方に入っている要素だけを集めたもの"], ["∪（カップ）", "和集合を表す記号。AとBのどちらか一方にでも入っている要素をすべて集めたもの"]], "think": "「両方に共通するもの」なのか「どちらか一方にあるもの全部」なのかで記号が変わる、という対応を押さえる。∩は下向きの器（キャップ）で「重なった部分だけをすくい取る」イメージ、∪は上向きの器（カップ）で「両方まとめて受け止める」イメージで覚えると混同しにくい。", "vs": "∪（和集合、どちらか一方にでもあれば含む＝範囲が広い）と∩（積集合、両方に共通する部分だけ＝範囲が狭い）を取り違えやすい。「共通」という言葉が出てきたら∩、「どちらか」「すべて」という言葉が出てきたら∪、と言葉で区別するとよい。", "opt": ["正解。∩は積集合（共通部分）の記号で、AとBの両方に入っている要素だけを集めたもの。", "∪は和集合の記号であり、AとBのどちらか一方にでも入っている要素をすべて集めたもので、共通部分だけを指す記号ではない。", "⊂は部分集合の記号であり、ある集合がもう一つの集合にすっぽり含まれるという包含関係を表すもので、2つの集合の共通部分を表す記号ではない。", "∈は要素であることを表す記号であり、あるものが集合に含まれているかどうかという所属を表すもので、2つの集合を組み合わせる記号ではない。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>積集合(∩)はAとBが重なる部分だけ</text><circle cx=''130'' cy=''80'' r=''45'' fill=''none'' stroke=''#60a5fa'' stroke-width=''2''/><circle cx=''190'' cy=''80'' r=''45'' fill=''none'' stroke=''#c9a04a'' stroke-width=''2''/><text x=''95'' y=''55'' font-size=''10'' fill=''#60a5fa''>A</text><text x=''225'' y=''55'' font-size=''10'' fill=''#c9a04a''>B</text><text x=''160'' y=''83'' text-anchor=''middle'' font-size=''9'' fill=''#e8eaf0''>A∩B</text><text x=''170'' y=''125'' text-anchor=''middle'' font-size=''9'' fill=''#8892a4''>重なる部分だけがA∩B</text></svg>"}'),

  ('g-kentei-k-q29', '8. AIに必要な数理・統計知識',
   '「写像（関数）」の説明として最も適切なものはどれか。',
   NULL::text,
   '["ある集合（定義域）の要素それぞれに、別の集合（値域）の要素をただ1つ対応させる規則のこと", "ある集合の要素それぞれに対して、別の集合の要素を複数個まとめて対応させるような規則のこと", "2つの集合に共通して含まれる要素だけを取り出して、新しい1つの集合を作るような操作のこと", "ある集合の要素の個数と、別の集合の要素の個数が等しいかどうかを比べるような操作のこと"]',
   0, '[0]', 'single',
   '{"asked": "写像（関数）の定義そのもの、「1つの入力に1つの出力を対応させる規則」という考え方を選ぶ問題。", "why_asked": "ニューラルネットワークの各層も、突き詰めれば「入力を受け取って出力を返す写像」の組み合わせ。AIの数式を読むうえで、写像・関数という言葉が指す中身を土台として押さえておく必要がある。", "kid": "写像（しゃぞう）とは、ざっくり言うと「入力を1つ決めたら、出力が1つに決まる対応のルール」のこと。「関数」という言葉とほぼ同じ意味で使われる。例えば「ある人の身長を入れたら、その人の体重が1つ返ってくる」というような、入力と出力のペアを決めるルールが写像。", "eg": "たとえるなら、自動販売機のボタンのようなもの。ある1つのボタン（入力）を押すと、出てくる飲み物（出力）はいつも1本に決まっている。同じボタンを押したのに、ある時は2本出てきたり、何も出てこなかったりはしない。この「1つ押したら1つ出る」という対応の決まりが写像。", "terms": [["写像（しゃぞう）", "ある集合の要素それぞれに対して、別の集合の要素をただ1つずつ対応させる規則。「関数」とほぼ同じ意味で使われる"], ["定義域（ていぎいき）", "写像に入力として入れてよい値の集合。自動販売機で言えば、押せるボタンの集まり"], ["値域（ちいき）", "写像から実際に出力として出てくる値の集合。自動販売機で言えば、実際に出てくる飲み物の集まり"]], "think": "「1つの入力に対して出力がただ1つに決まるか」を判定基準にする。出力が複数出たり、決まらなかったりするものは写像ではない。定義域（入力として使える範囲）と値域（出力として出てくる範囲）をセットで理解しておくと、後で出てくる活性化関数（シグモイド関数やReLU関数）も「入力を1つ受け取って出力を1つ返す写像の一種」だと素直に読める。", "vs": "「1つの入力から複数の出力が出る」規則は写像とは呼ばない。逆に、複数の入力が同じ1つの出力に集まることは写像として問題ない（例：身長170cmの人が複数いても、体重という出力はそれぞれ1つに決まる）が、1つの入力から出力が2つ以上出たり、出力が決まらなかったりするものは写像ではない。", "opt": ["正解。写像とは、ある集合の要素それぞれに対して、別の集合の要素をただ1つずつ対応させる規則のこと。", "1つの入力に対して出力を複数個まとめて対応させてしまうと、出力が1つに定まらず、写像の定義から外れてしまう。", "これは集合の「積集合」の説明であり、2つの集合に共通する要素だけを取り出す操作であって、入力と出力を対応させる規則ではない。", "これは集合の「要素数の比較」の説明であり、写像そのものではなく、写像が存在するかどうかを調べる際に補助的に使われることがある考え方にすぎない。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>1つの入力に出力はただ1つ</text><ellipse cx=''90'' cy=''80'' rx=''55'' ry=''45'' fill=''none'' stroke=''#2a2f3f'' stroke-width=''1''/><ellipse cx=''250'' cy=''80'' rx=''55'' ry=''45'' fill=''none'' stroke=''#2a2f3f'' stroke-width=''1''/><text x=''90'' y=''35'' text-anchor=''middle'' font-size=''9'' fill=''#8892a4''>定義域</text><text x=''250'' y=''35'' text-anchor=''middle'' font-size=''9'' fill=''#8892a4''>値域</text><circle cx=''90'' cy=''60'' r=''3'' fill=''#e8eaf0''/><circle cx=''90'' cy=''85'' r=''3'' fill=''#e8eaf0''/><circle cx=''90'' cy=''105'' r=''3'' fill=''#e8eaf0''/><circle cx=''250'' cy=''65'' r=''3'' fill=''#e8eaf0''/><circle cx=''250'' cy=''100'' r=''3'' fill=''#e8eaf0''/><line x1=''93'' y1=''60'' x2=''247'' y2=''65'' stroke=''#60a5fa'' stroke-width=''1.5''/><line x1=''93'' y1=''85'' x2=''247'' y2=''65'' stroke=''#60a5fa'' stroke-width=''1.5''/><line x1=''93'' y1=''105'' x2=''247'' y2=''100'' stroke=''#60a5fa'' stroke-width=''1.5''/><text x=''170'' y=''128'' text-anchor=''middle'' font-size=''9'' fill=''#8892a4''>どの入力からも出力は1本の矢印だけ</text></svg>"}'),

  ('g-kentei-k-q30', '8. AIに必要な数理・統計知識',
   'ネイピア数e（自然対数の底）についての説明として最も適切なものはどれか。',
   NULL::text,
   '["およそ2.718という値をとる定数で、微分・積分や指数関数の計算がきれいになる", "円の直径に対する円周の長さの比を表す定数で、およそ3.14という値をとり、図形の計算によく使われる", "0から1までの範囲で確率の大小を比較するときにだけ使われる、確率計算専用の特別な記号", "測定のばらつきを打ち消すために平均を取る計算のときにだけ使われる、統計専用の係数"]',
   0, '[0]', 'single',
   '{"asked": "ネイピア数e（自然対数の底）が「およそ2.718というただの定数」であることと、その使いどころを選ぶ問題。", "why_asked": "シグモイド関数の式（1を、1にeのマイナスx乗を足したもので割る形）など、機械学習の数式にeが繰り返し登場する。eを円周率πのような「意味のある特別な定数」として素朴に理解しておくと、数式を見たときに身構えずに読める。", "kid": "e（ネイピア数、と読む）は、円周率πが「およそ3.14」という決まった値をとる定数であるのと同じように、「およそ2.718」という決まった値をとる定数。円周率が円に関する計算で自然に出てくるのと同じように、eは「増え方・減り方」に関する計算（微分・積分）で自然に出てくる数。自然対数（しぜんたいすう）ln（エルエヌ、と読む）は、このeを底（てい、掛け算を繰り返すもとの数）にした対数のこと。", "eg": "たとえるなら、貯金が「1年ごとにまとめて増える」のではなく「刻一刻と絶え間なく増え続ける」としたら、1年後に増える倍率はちょうどeという数に近づく、という性質がある。連続的に増え続ける現象を計算するときに、自然とeという数が顔を出す。", "terms": [["ネイピア数e", "およそ2.718という値をとる定数。円周率πと同じく、決まった値を持つ特別な数"], ["自然対数ln（エルエヌ）", "eを底にした対数。「eを何乗したらこの値になるか」を答える計算"], ["シグモイド関数", "出力を0〜1の範囲に押し込める関数で、式の中にeのマイナス乗が使われている"]], "think": "eは円周率と同じ「ただの定数」だと捉えるのが出発点。特別なのは値そのものではなく、微分・積分の計算がeを底にするときだけ驚くほどシンプルになるという性質。だからこそ指数関数・対数関数を扱う数式に繰り返し登場し、シグモイド関数のような機械学習の式にも自然に組み込まれている。", "vs": "円周率π（円の直径と円周の長さの比）と混同しやすいが、eは円ではなく「連続的な増え方・減り方」に関する定数という点で由来が異なる。どちらも「およそ○○」という決まった値を持つ定数である点は共通している。", "opt": ["正解。eはおよそ2.718という値をとる定数で、微分・積分や指数関数の計算に向いており、シグモイド関数など機械学習の数式にもよく登場する。", "円の直径に対する円周の長さの比はπ（円周率、およそ3.14）の説明であり、eの説明ではない。", "eは確率専用の記号ではなく、微分・積分や指数関数の計算全般で使われる、値が決まった定数である。", "eは統計専用の係数ではなく、測定誤差の打ち消しとも直接関係のない、値が決まった定数である。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>eのx乗のグラフ（急激に増える形）</text><line x1=''30'' y1=''115'' x2=''310'' y2=''115'' stroke=''#2a2f3f'' stroke-width=''1''/><line x1=''30'' y1=''115'' x2=''30'' y2=''20'' stroke=''#2a2f3f'' stroke-width=''1''/><path d=''M 30 110 C 100 108 180 90 240 40 C 260 25 275 15 290 8'' fill=''none'' stroke=''#60a5fa'' stroke-width=''2''/><circle cx=''150'' cy=''88'' r=''2.5'' fill=''#c9a04a''/><text x=''120'' y=''78'' font-size=''9'' fill=''#c9a04a''>x=1のときy=e≈2.718</text><text x=''285'' y=''128'' font-size=''9'' fill=''#8892a4''>x</text><text x=''15'' y=''25'' font-size=''9'' fill=''#8892a4''>y</text></svg>"}'),

  ('g-kentei-k-q31', '8. AIに必要な数理・統計知識',
   'Σ（シグマ）という記号の意味として最も適切なものはどれか。',
   NULL::text,
   '["決まった範囲の番号について、それぞれの値を計算してから全部足し合わせる「総和」を表す記号", "決まった範囲の番号について、それぞれの値を計算してから全部掛け合わせる「総積」を表す記号", "たくさんの数の中から、最も大きい値だけを選び出す操作を表す記号", "たくさんの数を、大きい順または小さい順に並べ替える操作を表す記号"]',
   0, '[0]', 'single',
   '{"asked": "Σ（シグマ）が「何番目から何番目までを全部足し合わせる」という総和を表す記号であることを選ぶ問題。", "why_asked": "損失関数や平均の式など、機械学習の数式には「全データについて何かを計算して、全部足す」という操作が繰り返し出てくる。この「全部足す」を短く書くための記号がΣであり、これを読めないと数式全体が長い呪文に見えてしまう。", "kid": "Σ（シグマ、と読む）は「足し算をまとめて書くための記号」。例えば「1番目のデータから10番目のデータまで、それぞれの値を全部足し合わせる」という長い作業を、Σという1つの記号と、その上下に書かれた「どこから」「どこまで」という番号だけで短く表せる。", "eg": "たとえるなら、1組から10組までの各クラスの人数を、1組の人数＋2組の人数＋…＋10組の人数、と1つずつ書く代わりに、「1組から10組までの人数を全部足す」とひとことで済ませるようなもの。Σはその「まとめて全部足す」を記号にしたもの。", "terms": [["Σ（シグマ）", "決まった範囲について、それぞれの値を計算してから全部足し合わせる「総和」を表す記号"], ["下端・上端", "Σの下に書く「どこから始めるか」の番号と、上に書く「どこで終わるか」の番号。この範囲の分だけ足し算を繰り返す"]], "think": "Σを見たら、まず「何を」「どこからどこまで」足すのかの2点を確認する。Σの下に書かれた番号が足し始める場所、上に書かれた番号が足し終わる場所を表し、その間の番号を1つずつ当てはめながら計算した値を、最後に全部合計する、という手順を1つの記号で圧縮して書いているだけだと捉えるとよい。", "vs": "掛け算をまとめて表す記号（Π、パイと読む、総積）と混同しやすいが、Σはあくまで「足し算」をまとめる記号であり、「掛け算」をまとめる記号ではない。", "opt": ["正解。Σは決まった範囲の番号それぞれについて値を計算し、全部足し合わせる「総和」を表す記号。", "全部を掛け合わせる「総積」を表す記号はΠ（パイ）であり、Σは足し算をまとめる記号である。", "最大値だけを選び出す操作は別の記号（maxなど）で表され、Σは範囲全体を足し合わせる操作を表す記号である。", "数を並べ替える操作とΣは無関係であり、Σは範囲全体の値を足し合わせて1つの数にまとめる記号である。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>Σは棒の高さを全部足し合わせる</text><line x1=''30'' y1=''115'' x2=''310'' y2=''115'' stroke=''#2a2f3f'' stroke-width=''1''/><rect x=''50'' y=''95'' width=''30'' height=''20'' fill=''#60a5fa''/><rect x=''100'' y=''80'' width=''30'' height=''35'' fill=''#60a5fa''/><rect x=''150'' y=''60'' width=''30'' height=''55'' fill=''#60a5fa''/><rect x=''200'' y=''90'' width=''30'' height=''25'' fill=''#60a5fa''/><rect x=''250'' y=''70'' width=''30'' height=''45'' fill=''#60a5fa''/><text x=''65'' y=''128'' font-size=''9'' fill=''#8892a4''>1</text><text x=''115'' y=''128'' font-size=''9'' fill=''#8892a4''>2</text><text x=''165'' y=''128'' font-size=''9'' fill=''#8892a4''>3</text><text x=''215'' y=''128'' font-size=''9'' fill=''#8892a4''>4</text><text x=''265'' y=''128'' font-size=''9'' fill=''#8892a4''>5</text><text x=''170'' y=''30'' text-anchor=''middle'' font-size=''9'' fill=''#c9a04a''>Σ = 全部の高さの合計</text></svg>"}'),

  ('g-kentei-k-q32', '8. AIに必要な数理・統計知識',
   '積分（せきぶん）についての説明として最も適切なものはどれか。',
   NULL::text,
   '["グラフと横軸の間にできる部分の「面積」を求める計算で、微分の逆演算にあたる", "グラフのある1点における接線の「傾き」を求める計算で、微分と同じ操作を指す", "複数のデータを大きい順に並べ替えてから、真ん中の値を取り出す計算", "グラフ全体を、原点を中心に180度回転させて描き直す操作"]',
   0, '[0]', 'single',
   '{"asked": "積分が「グラフと横軸で囲まれた面積を求める計算」であり、微分の逆演算にあたることを選ぶ問題。", "why_asked": "確率密度関数の下側の面積が確率を表す、といった場面で積分の考え方が出てくる。式を暗記するのではなく「面積を求めている」というイメージを持てているかを問う基礎問題。", "kid": "積分とは、グラフの線と横の軸（横軸）の間にできる部分の「面積」を求める計算のこと。長方形や三角形のようにまっすぐな図形なら、たて×よこなどの公式で面積を計算できるが、曲がったグラフの場合はそういう単純な公式が使えない。積分は、そういう曲がった形の面積でも求められるようにした計算方法。", "eg": "たとえるなら、まっすぐな道のりなら定規で測れるが、うねうねと曲がりくねった土地の面積を測りたいとき、その土地を極めて細い短冊にたくさん切り分けて、それぞれの短冊の面積（ほぼ長方形とみなせる）を全部足し合わせる、というイメージ。積分はこの「細かく切って全部足す」という考え方を、数式できっちり行う計算。", "terms": [["積分", "グラフと横軸の間にできる部分の面積を求める計算"], ["微分", "グラフのある1点における接線の傾き（増え方の勢い）を求める計算"], ["微分の逆演算", "積分は微分と逆向きの関係にあり、微分してできた結果を積分するともとの関数に戻るという性質"]], "think": "「面積を求めている」という1点だけをまず押さえる。そのうえで、積分と微分は表裏の関係にあり、ある関数を微分して得られた結果を積分すると、もとの関数に戻るという性質がある。この「逆演算」という関係性は、公式を丸暗記しなくても、面積を求める操作と傾きを求める操作が互いに打ち消し合う、という因果としてイメージできる。", "vs": "微分（傾きを求める）と混同しやすいが、積分は面積を求める計算であり、向きが逆。微分は「そのグラフがどれくらいの勢いで増減しているか」を1点ごとに調べる計算、積分は「そのグラフの下にどれだけの量がたまっているか」を範囲全体でまとめて調べる計算、と役割で区別するとよい。", "opt": ["正解。積分はグラフと横軸の間にできる部分の面積を求める計算で、微分の逆演算にあたる。", "ある1点における接線の傾きを求める計算は微分の説明であり、積分は面積を求める計算である。", "データを並べ替えて真ん中の値を取り出す操作は中央値の説明であり、積分とは異なる。", "グラフを180度回転させる操作は積分とは無関係であり、積分はあくまで面積を求める計算である。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>積分はグラフと横軸の間の面積</text><line x1=''30'' y1=''115'' x2=''310'' y2=''115'' stroke=''#2a2f3f'' stroke-width=''1''/><line x1=''30'' y1=''115'' x2=''30'' y2=''25'' stroke=''#2a2f3f'' stroke-width=''1''/><path d=''M 60 100 Q 170 30 280 90 L 280 115 L 60 115 Z'' fill=''#60a5fa'' fill-opacity=''0.35'' stroke=''none''/><path d=''M 60 100 Q 170 30 280 90'' fill=''none'' stroke=''#60a5fa'' stroke-width=''2''/><text x=''170'' y=''105'' text-anchor=''middle'' font-size=''9'' fill=''#e8eaf0''>この面積を求める</text></svg>"}'),

  ('g-kentei-k-q33', '8. AIに必要な数理・統計知識',
   '「テイラー展開」の考え方の説明として最も適切なものはどれか。',
   NULL::text,
   '["複雑な曲線を持つ関数を、ある1点のまわりだけに注目して、扱いやすい多項式で近似する考え方", "複雑な曲線を持つ関数を、いくつかの単純な図形に分解して、それぞれの面積を正確に足し合わせる考え方", "複数の変数を持つ関数を、変数が1つだけの関数に置き換えて、計算の手間を完全になくす考え方", "ばらつきのあるデータを、平均値だけを使ってすべて同じ値に揃えてしまう考え方"]',
   0, '[0]', 'single',
   '{"asked": "テイラー展開が「ある点のまわりで、複雑な関数を直線や放物線などの多項式で近似する」考え方であることを選ぶ問題。", "why_asked": "最適化アルゴリズムの理論的な背景（ニュートン法など）で「関数をその点の近くだけ多項式で近似する」という考え方が土台になっている。数式そのものより、この「近似する」という発想を持っているかが問われる。", "kid": "世の中の複雑にうねうねと曲がった関数のグラフも、ものすごく近くまでズームして、ある1点のすぐ周りだけを見ると、ほとんどまっすぐな直線に見えてくる。もう少し範囲を広げて見ると、今度は放物線（お椀のような形）くらいの単純な形で近い動きをする。テイラー展開は、この「近くだけを見れば単純な形で近似できる」という発想を使って、複雑な関数を扱いやすい多項式（直線・放物線・もっと高次の式）に置き換える考え方。", "eg": "たとえるなら、地球は丸いのに、自分の家の庭にいるときは地面が平らに見えるようなもの。本当は曲がっているのに、ごく近い範囲だけを見れば、平ら（＝直線）とみなしても実用上ほとんど問題ない。もっと精度が欲しければ、平らではなく緩やかにカーブした形（＝放物線）で近似すれば、もう少し広い範囲まで正確に扱える。", "terms": [["近似（きんじ）", "本当の値とは完全には一致しないが、実用上十分に近い、扱いやすい形に置き換えること"], ["多項式（たこうしき）", "足し算・掛け算・累乗だけで作られる、直線や放物線のような扱いやすい式のこと"], ["ニュートン法", "テイラー展開の考え方を使って、関数の傾きの情報から少しずつ最適な点に近づいていく計算手法。勾配降下法とも関係が深い"]], "think": "「複雑な関数をそのまま扱うのは大変だが、ある1点の近くだけなら単純な形で近似できる」という発想が核心。近似に使う多項式の次数を増やすほど（直線→放物線→さらに複雑な式）、近似できる範囲は広がり、精度も上がっていく、という関係性を押さえておけば十分で、展開式そのものを暗記する必要はない。", "vs": "面積を求める積分や、変数を減らす次元削減と混同しやすいが、テイラー展開はあくまで「ある点のまわりでの近似」であり、面積の計算でも変数の数を減らす操作でもない。", "opt": ["正解。テイラー展開は、ある1点のまわりに注目して、複雑な関数を直線や放物線のような扱いやすい多項式で近似する考え方。", "図形に分解して面積を正確に足し合わせるのは積分の考え方に近く、ある点のまわりでの近似とは異なる。", "変数を1つに減らして計算の手間をなくす操作ではなく、変数の数はそのままに、関数の形を近似する考え方である。", "平均値だけを使ってデータを揃える操作とは異なり、テイラー展開はあくまで関数の形をある点のまわりで近似する考え方である。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>ある点の近くを直線や放物線で近似</text><line x1=''30'' y1=''115'' x2=''310'' y2=''115'' stroke=''#2a2f3f'' stroke-width=''1''/><path d=''M 30 100 C 100 20 200 20 290 105'' fill=''none'' stroke=''#e8eaf0'' stroke-width=''2''/><line x1=''120'' y1=''95'' x2=''230'' y2=''35'' stroke=''#60a5fa'' stroke-width=''1.5'' stroke-dasharray=''4,3''/><circle cx=''175'' cy=''65'' r=''3'' fill=''#c9a04a''/><text x=''175'' y=''55'' text-anchor=''middle'' font-size=''9'' fill=''#c9a04a''>この点のまわり</text><text x=''232'' y=''30'' font-size=''9'' fill=''#60a5fa''>直線で近似</text><text x=''45'' y=''90'' font-size=''9'' fill=''#8892a4''>元の複雑な曲線</text></svg>"}'),

  ('g-kentei-k-q34', '8. AIに必要な数理・統計知識',
   '「勾配ベクトル（grad）」の説明として最も適切なものはどれか。',
   NULL::text,
   '["複数の変数それぞれについての偏微分を並べたベクトルで、関数の値が最も急に増える方向を指す", "複数の変数それぞれについての偏微分を並べたベクトルで、関数の値が最も緩やかに増える方向を指す", "1つの変数についての微分の結果だけを取り出し、他の変数をすべて無視して計算した値", "関数の出力の中から、最も小さい値だけを取り出して並べたベクトル"]',
   0, '[0]', 'single',
   '{"asked": "勾配ベクトルが「各変数についての偏微分を並べたベクトル」であり「関数の値が最も急に増える方向」を指すことを選ぶ問題。", "why_asked": "勾配降下法という機械学習の最適化手法の名前の由来そのもの。「勾配の逆方向に進むと損失関数が減っていく」という説明を理解するには、勾配ベクトルが何を指しているかを押さえておく必要がある。", "kid": "変数が1つだけの関数なら、微分すると「傾き」という1つの数が出てくる。変数が複数ある関数（例えば「体重は身長と年齢で決まる」のように、入力が2つ以上ある関数）の場合、それぞれの変数について別々に傾きを計算したもの（偏微分）を、1つのベクトル（矢印）としてまとめたものが勾配ベクトル。この矢印は、関数の値が最も急に増えていく方向を指している。", "eg": "たとえるなら、山の斜面に立っているときに、「東西方向にはどれくらいの急さか」「南北方向にはどれくらいの急さか」をそれぞれ調べて、それを1本の矢印にまとめたようなもの。その矢印は、その場所から最も急な登り坂の方向を指す。山を下りたいとき（損失関数を小さくしたいとき）は、この矢印とは逆の方向に進めばよい、というのが勾配降下法の考え方。", "terms": [["偏微分", "複数の変数を持つ関数について、1つの変数だけに注目し、他の変数は固定した状態で計算する微分"], ["勾配ベクトル（grad）", "すべての変数についての偏微分を並べたベクトル。関数の値が最も急に増える方向を指す"], ["勾配降下法", "勾配ベクトルとは逆の方向（最も急に減る方向）へ少しずつ進んでいくことで、損失関数を最小に近づけていく最適化の手法"]], "think": "勾配ベクトルは「各方向にどれだけ急に変化するか」をまとめて1本の矢印にしたもの、というイメージが核心。矢印が指す向きは値が増える方向であり、機械学習では損失関数を減らしたいので、勾配ベクトルの逆向きに一歩ずつ進む、という形で最適化に使われる。", "vs": "「最も緩やかに増える方向」と取り違えやすいが、勾配ベクトルが指すのは常に「最も急に増える方向」。だからこそ、その逆向きに進むことが「最も急に値を下げる」効率のよい方法になり、勾配降下法の名前の由来になっている。", "opt": ["正解。勾配ベクトルは各変数についての偏微分を並べたベクトルで、関数の値が最も急に増える方向を指す。", "勾配ベクトルが指すのは最も緩やかな方向ではなく、最も急に増える方向であり、説明が逆になっている。", "1つの変数だけに注目し他をすべて無視するのは偏微分そのものの計算であり、勾配ベクトルはすべての変数についての偏微分をまとめたものである。", "関数の出力から最小値だけを取り出す操作とは異なり、勾配ベクトルは各方向への変化の急さをまとめたベクトルである。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>等高線と、最も急に増える方向の矢印</text><ellipse cx=''170'' cy=''80'' rx=''120'' ry=''45'' fill=''none'' stroke=''#2a2f3f'' stroke-width=''1''/><ellipse cx=''170'' cy=''80'' rx=''80'' ry=''30'' fill=''none'' stroke=''#2a2f3f'' stroke-width=''1''/><ellipse cx=''170'' cy=''80'' rx=''40'' ry=''15'' fill=''none'' stroke=''#2a2f3f'' stroke-width=''1''/><circle cx=''170'' cy=''80'' r=''2.5'' fill=''#e8eaf0''/><line x1=''170'' y1=''80'' x2=''130'' y2=''55'' stroke=''#60a5fa'' stroke-width=''2''/><polygon points=''130,55 138,58 133,64'' fill=''#60a5fa''/><text x=''55'' y=''45'' font-size=''9'' fill=''#60a5fa''>勾配ベクトル（最も急に増える向き）</text></svg>"}'),

  ('g-kentei-k-q35', '8. AIに必要な数理・統計知識',
   '極限（lim）という考え方の説明として最も適切なものはどれか。',
   NULL::text,
   '["変数xをある値に限りなく近づけていったとき、関数の値がどこに近づいていくかを表す考え方", "変数xをある値に限りなく近づけていったとき、関数の値が実際にその値に到達したかどうかを確かめる考え方", "関数のグラフの中から、最も値が大きくなる1点だけを正確に探し出す考え方", "複数の関数のグラフを重ね合わせて、共通して通る点をすべて探し出す考え方"]',
   0, '[0]', 'single',
   '{"asked": "極限（lim）が「変数をある値に限りなく近づけたとき、関数の値がどこに近づいていくか」を表す考え方であることを選ぶ問題。", "why_asked": "微分の定義そのものが「限りなく近づける」という極限の考え方の上に成り立っている。接線の傾きを求める微分を理解する土台として、極限がどういう発想かを押さえておく必要がある。", "kid": "極限（きょくげん）とは、「変数xをある値にどんどん近づけていったとき、関数の値は最終的にどこに近づいていくか」を考える発想。大事なのは、xがその値に「実際にたどり着くかどうか」ではなく、「近づけば近づくほど、値がどこに落ち着いていくように見えるか」という点。微分は、この「限りなく近づける」という考え方を使って、接線の傾き（ある1点でのグラフの急さ）を定義している。", "eg": "たとえるなら、的の中心にどんどん矢を近づけていくとき、実際に中心にぴったり刺さらなくても、「矢はどんどん中心に近づいていっている」という様子そのものに注目するようなもの。極限は、この「近づいていく先」を考える発想であり、微分ではこれを使って「ものすごく短い区間での傾き」を求めている。", "terms": [["極限（lim、リムと読む）", "変数をある値に限りなく近づけたとき、関数の値がどこに近づいていくかを表す考え方"], ["微分の定義", "接線の傾きを、2点間の距離を限りなく0に近づけたときの極限として定義したもの"]], "think": "「実際に到達するかどうか」ではなく「近づけていくとどこに落ち着くように見えるか」という視点の違いを押さえるのが核心。微分は、グラフ上の2点をどんどん近づけていき、その間の傾き（変化の割合）が最終的にどんな値に近づくかを極限で求めることで、「ある1点だけでの傾き」という一見矛盾した量を定義できるようにしている。", "vs": "「実際にその値に到達したかどうかを確かめる」という説明と混同しやすいが、極限はあくまで「近づいていった先に何があるように見えるか」を考える発想であり、実際に到達するかどうかは問題にしない。", "opt": ["正解。極限は、変数をある値に限りなく近づけていったとき、関数の値がどこに近づいていくかを表す考え方。", "実際にその値に到達したかどうかを確かめる操作とは異なり、極限は近づけていった先に値がどこに落ち着くように見えるかを考える発想である。", "グラフの中から最大値の点を1つ探し出す操作とは異なり、極限はある値に近づけたときの関数の値の行き先を考える考え方である。", "複数の関数の交点をすべて探す操作とは異なり、極限は1つの関数について変数を近づけたときの値の行き先を考える考え方である。"], "viz": "<svg viewBox=''0 0 340 140'' xmlns=''http://www.w3.org/2000/svg''><text x=''170'' y=''18'' text-anchor=''middle'' font-size=''11'' fill=''#8892a4''>xをある値に近づけると値はここに近づく</text><line x1=''30'' y1=''115'' x2=''310'' y2=''115'' stroke=''#2a2f3f'' stroke-width=''1''/><line x1=''170'' y1=''115'' x2=''170'' y2=''25'' stroke=''#2a2f3f'' stroke-width=''1'' stroke-dasharray=''3,3''/><path d=''M 40 100 C 100 80 150 55 168 45'' fill=''none'' stroke=''#60a5fa'' stroke-width=''2''/><path d=''M 172 45 C 190 55 240 80 300 100'' fill=''none'' stroke=''#60a5fa'' stroke-width=''2''/><circle cx=''170'' cy=''45'' r=''3'' fill=''#c9a04a''/><line x1=''30'' y1=''45'' x2=''170'' y2=''45'' stroke=''#8892a4'' stroke-width=''1'' stroke-dasharray=''3,3''/><text x=''285'' y=''128'' font-size=''9'' fill=''#8892a4''>x</text><text x=''35'' y=''38'' font-size=''9'' fill=''#c9a04a''>値はここに近づく</text></svg>"}'),

  ('g-kentei-k-q36', '8. AIに必要な数理・統計知識',
   '正方行列（縦と横の数が同じ行列）に対して、ただ1つの数値を対応させる計算がある。この数値は、その行列が表す変換によって面積や体積が何倍に拡大・縮小されるかを表しており、この値が0だと逆行列が存在しない。この数値を何と呼ぶか。',
   NULL::text,
   '["行列式（determinant）", "固有値（eigenvalue）", "トレース（trace、対角成分の和）", "ランク（rank、階数）"]',
   0, '[0]', 'single',
   '{"asked": "正方行列に対して定まる、面積・体積の拡大縮小率を表す1つの数値の名前を問う問題。", "why_asked": "行列式は逆行列の存在条件（行列式が0だと逆行列がない）と直結しており、線形代数の基本用語として頻出。", "kid": "行列式（ぎょうれつしき）は、正方行列という「縦の数と横の数が同じ、数字を並べた表」に対して計算できる、たった1つの数字のこと。この数字は、その行列を使って図形を変形させたとき、面積や体積がもとの何倍になるかを表している。たとえば行列式が2なら、変形後の面積はもとの2倍になる。", "eg": "たとえるなら、正方形の紙を斜めに引き伸ばしたり傾けたりする道具が行列で、行列式はその道具を使ったときに紙の面積が何倍に変わるかを表すメモのようなもの。行列式が0だと、紙がぺしゃんこに潰れて面積がなくなってしまう変形ということになる。", "terms": [["行列式（determinant）", "正方行列に対して1つ定まる数値。図形の面積・体積が変形によって何倍になるかを表す"], ["正方行列", "縦の数（行数）と横の数（列数）が同じ行列"], ["逆行列", "掛けると単位行列になる、行列の「割り算」にあたる行列。行列式が0だと存在しない"]], "think": "行列式は「行列を使って図形を変形させたときの面積・体積の倍率」という1つの意味に集約される。倍率が0ということは面積・体積が0に潰れてしまう変形なので、そこから元の形に戻す変形（逆行列）は作れない。だから行列式が0のとき逆行列は存在しない、という結び付きが生まれる。", "calc": {"steps": ["問題: 上の行が2と3、下の行が1と4に並んだ2×2の行列の行列式を求める", "ステップ1: 2×2の行列式は「左上×右下 − 右上×左下」で計算する", "ステップ2: 左上×右下を計算する。2×4=8", "ステップ3: 右上×左下を計算する。3×1=3", "ステップ4: 2つの結果を引き算する。8−3=5", "答え: 行列式は5"], "formula": "行列式 = (左上×右下) − (右上×左下) = (2×4) − (3×1) = 8 − 3 = 5"}, "vs": "固有値やトレース（対角成分の和）も正方行列から計算できる数値だが、行列式は面積・体積の倍率という意味を持つ点で異なる。固有値は向きが変わらない特別な方向における伸び縮み率、トレースは対角線上の数字を単純に足しただけの値であり、どちらも行列式とは計算方法も意味も別。", "opt": ["正解。正方行列に対して定まる、面積・体積の拡大縮小率を表す数値。0になると逆行列が存在しない。", "固有値は、変形後も向きが変わらない特別な方向における伸び縮みの倍率を表す数値で、面積・体積全体の倍率を表す行列式とは意味が異なる。", "トレースは対角線上に並んだ数字を単純に足し合わせた値で、面積・体積の倍率という意味は持たない。", "ランクは行列が実質的に何次元分の情報を持っているかを表す数値で、面積・体積の倍率を表す行列式とは別の指標。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"30\" y=\"20\" font-size=\"10\" fill=\"#8892a4\">変形前</text><rect x=\"30\" y=\"30\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><text x=\"34\" y=\"105\" font-size=\"9\" fill=\"#8892a4\">面積 = 1</text><text x=\"145\" y=\"65\" font-size=\"16\" fill=\"#60a5fa\">→</text><text x=\"122\" y=\"85\" font-size=\"9\" fill=\"#8892a4\">行列で変形</text><text x=\"235\" y=\"20\" font-size=\"10\" fill=\"#8892a4\">変形後</text><polygon points=\"220,90 285,90 315,30 250,30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"222\" y=\"115\" font-size=\"9\" fill=\"#c9a04a\">面積 = 行列式の値</text></svg>"}'),

  ('g-kentei-k-q37', '8. AIに必要な数理・統計知識',
   'ある正方行列に掛け合わせると、結果が単位行列（掛け算の1にあたる特別な行列）になるような行列を何と呼ぶか。連立方程式を行列の形で解くときに使われる。',
   NULL::text,
   '["逆行列（inverse matrix）", "転置行列（行と列を入れ替えた行列）", "単位行列（対角線が1で他が0の行列）", "ゼロ行列（すべての成分が0の行列）"]',
   0, '[0]', 'single',
   '{"asked": "ある行列に掛けると単位行列になる、特別な行列の名前を問う問題。", "why_asked": "逆行列は連立方程式を行列の形で解く手段として使われ、行列式が0だと存在しないなど、行列式・単位行列とセットで理解すべき基本用語。", "kid": "逆行列（ぎゃくぎょうれつ）は、ある正方行列に掛け算すると、単位行列という特別な行列（掛け算の1にあたる行列）になるような、もう1つの行列のこと。ふつうの数で言えば、5に対する「5分の1」（5を掛けると1になる数）のような関係にあたる。", "eg": "たとえるなら、ある変形をしたあとに、もとの形にぴったり戻す「巻き戻し」の変形が逆行列。行列Aで図形を変形させたあと、Aの逆行列でもう一度変形させると、最初の図形にきっちり戻る。", "terms": [["逆行列（inverse matrix）", "ある正方行列に掛けると単位行列になる行列。連立方程式を解く手段として使われる"], ["単位行列", "対角線が1で他が0の、掛け算の1にあたる特別な行列"], ["連立方程式", "複数の未知数を含む式を組み合わせたもの。行列の形にまとめて逆行列で解ける"]], "think": "「掛けると単位行列になる」という1点だけで逆行列は定義される。連立方程式は行列とベクトルの掛け算の形に書き直せるので、両辺に逆行列を掛ければ、単位行列が掛かった側（つまり求めたい未知数そのもの）だけが残り、答えが求まる。", "calc": {"steps": ["問題: 対角線上に2と4が並んだ行列Aに対して、対角線上に0.5と0.25が並んだ行列Bを掛けたとき、単位行列になるか確かめる", "ステップ1: 行列の左上同士を掛ける。2×0.5=1", "ステップ2: 行列の右下同士を掛ける。4×0.25=1", "ステップ3: 対角線以外の成分はもともと0なので、掛け算の結果も0のまま", "答え: 対角線が1、他が0の行列になった。これは単位行列そのものなので、BはAの逆行列である"], "formula": "A × B = [[2×0.5, 0], [0, 4×0.25]] = [[1,0],[0,1]] = 単位行列"}, "vs": "転置行列は行と列を入れ替えるだけの操作で、単位行列になるとは限らない。単位行列そのものと逆行列も別物で、単位行列は掛けても相手を変えない行列、逆行列は相手を単位行列に変える行列という違いがある。", "opt": ["正解。ある行列に掛けると単位行列になる行列。連立方程式を解く手段として使われる。", "転置行列は行と列を入れ替えるだけの操作で作られる行列で、元の行列に掛けても単位行列になるとは限らない。", "単位行列は対角線が1で他が0の、掛けても相手を変えない特別な行列であり、他の行列を単位行列に変える逆行列とは役割が逆。", "ゼロ行列はすべての成分が0の行列で、どんな行列と掛け合わせてもゼロ行列にしかならず、単位行列を作ることはできない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"45\" width=\"40\" height=\"40\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"15\" y=\"100\" font-size=\"9\" fill=\"#8892a4\">元の図形</text><text x=\"90\" y=\"60\" font-size=\"12\" fill=\"#60a5fa\">→</text><text x=\"72\" y=\"75\" font-size=\"9\" fill=\"#8892a4\">行列A</text><polygon points=\"140,90 190,90 210,45 160,45\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"140\" y=\"105\" font-size=\"9\" fill=\"#8892a4\">変形後</text><text x=\"240\" y=\"60\" font-size=\"12\" fill=\"#c9a04a\">→</text><text x=\"222\" y=\"75\" font-size=\"9\" fill=\"#8892a4\">逆行列</text><rect x=\"280\" y=\"45\" width=\"40\" height=\"40\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"262\" y=\"100\" font-size=\"9\" fill=\"#c9a04a\">元の図形に戻る</text></svg>"}'),

  ('g-kentei-k-q38', '8. AIに必要な数理・統計知識',
   '対角線上の成分がすべて1で、それ以外の成分がすべて0であるような正方行列を何と呼ぶか。どんな行列に掛けても、相手の行列を変化させない、掛け算の1にあたる存在である。',
   NULL::text,
   '["単位行列（identity matrix）", "ゼロ行列（zero matrix）", "対角行列（diagonal matrix）", "逆行列（inverse matrix）"]',
   0, '[0]', 'single',
   '{"asked": "対角線が1、他が0という特別な形を持ち、掛けても相手を変えない行列の名前を問う問題。", "why_asked": "単位行列は逆行列の定義（掛けると単位行列になる行列）そのものに登場し、行列の基礎用語として避けて通れない。", "kid": "単位行列（たんいぎょうれつ）は、対角線（左上から右下へのライン）上の数字がすべて1で、それ以外の場所の数字がすべて0になっている、正方行列のこと。この行列をどんな行列に掛けても、掛けられた側の行列はまったく変化しない。ふつうの数で言う「1」と同じ役割を、行列の世界で果たしている。", "eg": "たとえるなら、どんな数に1を掛けてもその数のままであるのと同じように、どんな行列に単位行列を掛けても、その行列は変わらないまま。単位行列は行列の世界の「1」にあたる。", "terms": [["単位行列（identity matrix）", "対角線が1で他が0の正方行列。掛けても相手の行列を変化させない"], ["対角線", "正方行列の左上から右下へ並ぶ成分のライン"], ["対角行列", "対角線上の成分は自由な数値、他は0の行列。単位行列はその中で対角線がすべて1の特別な場合"]], "think": "単位行列は「対角線が1、他が0」という形だけで決まる。掛け算しても相手の行列の各成分がそのまま残るのは、対角線の1がその成分をそのまま拾い上げ、他の場所の0が余計な足し算を発生させないため。この性質が逆行列の定義（掛けると単位行列になる）の土台になっている。", "vs": "対角行列は対角線上に0以外の好きな数字が入ってよい、より広いグループの行列で、単位行列はその中で対角線がすべて1という特別な1つのケースにあたる。ゼロ行列とは正反対で、ゼロ行列を掛けると相手はすべて0に潰れてしまう。", "opt": ["正解。対角線が1で他が0の正方行列。掛けても相手の行列を変化させない、行列の世界の「1」にあたる存在。", "ゼロ行列はすべての成分が0の行列で、これを掛けると相手の行列はすべて0に潰れてしまい、変化させない単位行列とは正反対の性質を持つ。", "対角行列は対角線上に0以外の好きな数字が入ってよい、より広いグループの行列で、対角線がすべて1とは限らない。", "逆行列はある行列に掛けると単位行列になる行列であり、単位行列そのものとは役割が異なる。"]}'),

  ('g-kentei-k-q39', '8. AIに必要な数理・統計知識',
   '1つの行列を、性質の異なる3つの行列の掛け算に分解する手法があり、データの本質的な成分を取り出す働きから、次元削減や推薦システムなどに使われている。この手法を何と呼ぶか。',
   NULL::text,
   '["特異値分解（SVD）", "主成分分析（PCA）", "固有値分解（EVD）", "コレスキー分解"]',
   0, '[0]', 'single',
   '{"asked": "1つの行列を3つの行列の積に分解し、本質的な成分を取り出す手法の名前を問う問題。", "why_asked": "SVDは次元削減・推薦システム・画像圧縮など幅広い応用の土台になっている行列分解手法で、基礎数理として出題されやすい。", "kid": "特異値分解（とくいちぶんかい、SVD: Singular Value Decomposition=特異値分解）は、1つの行列を、役割の違う3つの行列の掛け算に分解する方法のこと。ちょうど1つの数を「素因数分解」して、その数を作っている本質的な部品（2×3×5のような）に分けるのと似ていて、行列を「回転させる部品」「引き伸ばす部品」「もう一度回転させる部品」の3つに分ける。この分解によって、データの中でとくに重要な成分から順に取り出せるようになる。", "eg": "たとえるなら、1曲の音楽を、ボーカル・ベース・ドラムのパートに分解して、それぞれの音量（重要度）を調べるようなもの。特異値分解では、行列の中に隠れていた「重要な成分」を音量順（大きい順）に並べて取り出せるので、音量の小さい成分を切り捨てれば、情報をあまり失わずにデータを小さくできる。これが次元削減の考え方につながる。", "terms": [["特異値分解（SVD: Singular Value Decomposition＝特異値分解）", "1つの行列を3つの行列の積（回転・引き伸ばし・回転）に分解する手法"], ["特異値", "分解したときに出てくる、各成分の重要度（大きさ）を表す数値。大きい順に並ぶ"], ["次元削減", "データの情報をなるべく保ったまま、扱う数字の個数（次元）を減らすこと"]], "think": "SVDは行列を3つの部品（回転・引き伸ばし・回転）に分けることで、行列の中に隠れている「重要な向き」と「その向きの重要度（特異値）」を可視化する。特異値が大きい成分ほどデータの本質を多く持っているので、特異値が小さい成分を切り捨てても、データの本質はあまり損なわれない。これが次元削減や、少ない成分でユーザーの好みを表す推薦システムに使われる理由。", "vs": "主成分分析（PCA）も『データの本質的な成分を取り出す』という目的は似ているが、PCAはデータの分散（ばらつき）が最大になる方向を探す考え方が出発点で、SVDはあらゆる行列を3つの行列の積に分解する、より一般的な計算手法という違いがある。実際にはPCAの計算の中でSVDが使われることも多い。", "opt": ["正解。1つの行列を3つの行列の積に分解し、データの本質的な成分を重要度順に取り出せるようにする手法。", "主成分分析はデータの分散が最大になる方向を新しい軸として選ぶ考え方が出発点で、あらゆる行列を3つの行列の積に分解する計算手法そのものとは指しているものが異なる。", "固有値分解も行列をいくつかの部品に分ける手法だが、正方行列にしか使えず、3つの行列に分解するSVDよりも適用できる範囲が狭い。", "コレスキー分解は、ある条件を満たす特別な行列を三角形の形をした行列の積に分解する手法で、次元削減や推薦システムの土台として使われる場面はSVDほど一般的ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"15\" y=\"45\" width=\"45\" height=\"45\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"20\" y=\"105\" font-size=\"9\" fill=\"#8892a4\">行列A</text><text x=\"72\" y=\"72\" font-size=\"12\" fill=\"#8892a4\">=</text><rect x=\"92\" y=\"45\" width=\"45\" height=\"45\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"94\" y=\"105\" font-size=\"8\" fill=\"#8892a4\">U（回転）</text><text x=\"149\" y=\"72\" font-size=\"12\" fill=\"#8892a4\">×</text><rect x=\"169\" y=\"45\" width=\"45\" height=\"45\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"155\" y=\"105\" font-size=\"8\" fill=\"#8892a4\">Σ（重要度）</text><text x=\"226\" y=\"72\" font-size=\"12\" fill=\"#8892a4\">×</text><rect x=\"246\" y=\"45\" width=\"45\" height=\"45\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"240\" y=\"105\" font-size=\"8\" fill=\"#8892a4\">Vᵀ（回転）</text></svg>"}'),

  ('g-kentei-k-q40', '8. AIに必要な数理・統計知識',
   '主成分分析（PCA）が、データを表す新しい軸（主成分）として選ぶのは、どのような方向か。',
   NULL::text,
   '["データの分散（ばらつき）が最大になる方向", "データの平均値からもっとも近い点を通る方向", "データの数値がすべて0に近づく方向", "元の座標軸ともっとも角度が近い方向"]',
   0, '[0]', 'single',
   '{"asked": "主成分分析（PCA）が新しい軸（主成分）として選ぶ方向の条件を問う問題。", "why_asked": "PCAの数理の核心は「分散最大化」という基準にあり、既習の固有値・固有ベクトルの計算と直結する形で出題されやすい。", "kid": "主成分分析（しゅせいぶんぶんせき、PCA: Principal Component Analysis＝主成分分析）は、データを新しい向きの軸で見直す方法。このとき選ばれる新しい軸は、その軸の上にデータを投影した（影を落とした）ときに、データの散らばり具合（分散）がいちばん大きくなる方向。データが大きく散らばっている方向ほど、データの違いをよく表している情報が多い、と考えるのがPCAの発想。", "eg": "たとえるなら、細長い形をした魚の群れを写真に撮るとき、魚が泳いでいる方向（横に長い方向）から撮ると、群れの広がりがいちばんよく写る。真上から撮ると群れが点の塊にしか見えない。PCAが選ぶ主成分の軸は、この「いちばん広がって見える向き」に当たる。", "terms": [["主成分分析（PCA: Principal Component Analysis＝主成分分析）", "データの分散が最大になる方向を新しい軸として選び、データをより少ない軸で表現し直す手法"], ["分散", "データが平均からどれくらい散らばっているかを表す値。大きいほど散らばりが大きい"], ["固有ベクトル", "行列による変形でも向きが変わらない特別な方向を表すベクトル。PCAでは分散が最大になる方向と一致する"]], "think": "PCAでは、データのばらつき方を表す共分散行列を作り、その固有値・固有ベクトルを計算する。固有ベクトルは「行列による変形でも向きが変わらない特別な方向」だったが、共分散行列に対してこれを計算すると、その方向はちょうど「データの分散が最大になる方向」と一致する。そして固有値の大きさが、その方向にどれだけ分散が集中しているかを表す。分散が最大の方向を選ぶことで、少ない軸でもデータの違いをよく残せる。", "vs": "分散が最大になる方向を選ぶという基準は、データが平均値に近いかどうかや、数値が0に近づくかどうかとは関係がない。PCAが見ているのはあくまで『データがどれだけ広がって散らばっているか』という散らばり方であり、値の大小そのものではない。", "opt": ["正解。データを投影したときに分散（散らばり具合）が最大になる方向を、新しい軸（主成分）として選ぶ。", "平均値に近い点を通ることは、分散が最大になる方向を選ぶという基準とは関係がなく、PCAが軸を選ぶ根拠にはならない。", "データの数値が0に近づく方向を探しても、データの散らばり具合を表す情報にはならず、PCAが求める主成分の考え方とは異なる。", "元の座標軸との角度の近さは、データそのものの散らばり方とは無関係な基準であり、分散最大化というPCAの基準とは別物。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"70\" cy=\"100\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"95\" cy=\"85\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"110\" cy=\"90\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"140\" cy=\"65\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"160\" cy=\"70\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"185\" cy=\"50\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"205\" cy=\"55\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"230\" cy=\"35\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"150\" cy=\"95\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"120\" cy=\"60\" r=\"2.5\" fill=\"#e8eaf0\"/><line x1=\"55\" y1=\"110\" x2=\"245\" y2=\"30\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"150\" y=\"20\" font-size=\"9\" fill=\"#60a5fa\">第一主成分（分散が最大の方向）</text></svg>"}'),

  ('g-kentei-k-q41', '8. AIに必要な数理・統計知識',
   'm行n列の行列と、p行q列の行列を掛け算できるのは、どのような条件を満たすときか。また掛け算の結果は何行何列の行列になるか。',
   NULL::text,
   '["nとpが等しいときに掛け算でき、結果はm行q列の行列になる", "mとpが等しいときに掛け算でき、結果はn行q列の行列になる", "nとqが等しいときに掛け算でき、結果はm行p列の行列になる", "m、n、p、qがすべて等しいときのみ掛け算でき、結果はm行m列の行列になる"]',
   0, '[0]', 'single',
   '{"asked": "m行n列の行列とp行q列の行列が掛け算できる条件と、結果の行列の大きさを問う問題。", "why_asked": "行列の積の形の条件（列数と行数が一致する必要がある）はニューラルネットワークの層と層をつなげるときの大きさ合わせの基本になっており、実務・試験の両方で頻出。", "kid": "行列の掛け算は、どんな大きさの行列同士でもできるわけではない。m行n列の行列とp行q列の行列を掛け算できるのは、前の行列の列（れつ、縦に並んだ数字の1本分）の数（n）と、後ろの行列の行（ぎょう、横に並んだ数字の1段分）の数（p）が同じときだけ。このとき掛け算の結果は、前の行列の行の数（m）と、後ろの行列の列の数（q）を使った、m行q列の行列になる。", "eg": "たとえるなら、レゴブロックをつなげるときに、片方の突起の数ともう片方のくぼみの数がぴったり合わないとつなげられないのと同じ。行列の掛け算では、前の行列の「横の長さ（列数n）」と、後ろの行列の「縦の長さ（行数p）」がぴったり合っていないと、掛け算という接続ができない。", "terms": [["行", "行列を横に並んだ数字の列として見たときの1段分。m行なら段が上からm個ある"], ["列", "行列を縦に並んだ数字の列として見たときの1列分。n列なら横にn個並んでいる"], ["m行n列の行列", "縦にm個、横にn個の数字が並んだ行列を表す書き方"]], "think": "行列の掛け算は、前の行列の各行と、後ろの行列の各列を、成分ごとに掛けて足し合わせる計算（内積）を、行と列の組み合わせの数だけ繰り返す操作。この『成分ごとに掛けて足す』ができるためには、前の行列の1行に並ぶ数の個数（列数n）と、後ろの行列の1列に並ぶ数の個数（行数p）が同じでなければならない。数が合わないと、掛けて足す相手がいない成分が出てきてしまう。結果の行列は、前の行列の行数mと後ろの行列の列数qを組み合わせた、m行q列の大きさになる。", "calc": {"steps": ["問題: 2行3列の行列と、3行4列の行列を掛け算できるか調べ、できるなら結果が何行何列になるか求める", "ステップ1: 前の行列の列数（3）と、後ろの行列の行数（3）を比べる", "ステップ2: 3と3で数が一致しているので、この2つの行列は掛け算できる", "ステップ3: 結果の行数は、前の行列の行数である2", "ステップ4: 結果の列数は、後ろの行列の列数である4", "答え: 2行4列の行列になる"], "formula": "2行3列 × 3行4列 → 3=3（一致）なので掛け算でき、結果は2行4列"}, "vs": "内側の数字（前の列数n・後ろの行数p）が一致するかどうかだけが条件で、外側の数字（前の行数m・後ろの列数q）は掛け算できるかどうかには関係しない。外側の数字は、結果の行列の大きさを決めるほうに使われる。", "opt": ["正解。nとpが等しいときに掛け算でき、結果はm行q列の行列になる。", "mとpが等しいかどうかは掛け算できるかどうかの条件には関係がなく、この基準で判断すると成分ごとの掛け算と足し算が対応しなくなる。", "nとqが等しいかどうかも掛け算できる条件には関係がなく、結果の行列の行数がpになるという点も実際の計算結果と合わない。", "4つの数字すべてが等しい必要はなく、内側の2つの数字（nとp）さえ一致していれば、外側の数字（mとq）が違っていても掛け算はできる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"45\" width=\"70\" height=\"45\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"40\" y=\"40\" font-size=\"10\" fill=\"#8892a4\">m行n列</text><text x=\"120\" y=\"72\" font-size=\"12\" fill=\"#8892a4\">×</text><rect x=\"150\" y=\"30\" width=\"45\" height=\"70\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"150\" y=\"115\" font-size=\"10\" fill=\"#8892a4\">p行q列</text><text x=\"90\" y=\"105\" font-size=\"9\" fill=\"#60a5fa\">n</text><text x=\"150\" y=\"20\" font-size=\"9\" fill=\"#60a5fa\">p</text><text x=\"215\" y=\"72\" font-size=\"9\" fill=\"#60a5fa\">n=pなら計算可</text><text x=\"255\" y=\"72\" font-size=\"12\" fill=\"#8892a4\">→</text><rect x=\"280\" y=\"45\" width=\"50\" height=\"45\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"278\" y=\"40\" font-size=\"9\" fill=\"#c9a04a\">m行q列</text></svg>"}'),

  ('g-kentei-k-q42', '8. AIに必要な数理・統計知識',
   'あるベクトルを、向きはそのままで、長さ（ノルム）がちょうど1になるように調整することを何と呼ぶか。調整してできたベクトルは何と呼ばれるか。',
   NULL::text,
   '["正規化と呼び、できたベクトルは単位ベクトルと呼ばれる", "転置と呼び、できたベクトルは基底ベクトルと呼ばれる", "内積と呼び、できたベクトルはゼロベクトルと呼ばれる", "射影と呼び、できたベクトルは固有ベクトルと呼ばれる"]',
   0, '[0]', 'single',
   '{"asked": "ベクトルの向きを保ったまま長さを1に調整する操作の名前と、その結果できるベクトルの名前を問う問題。", "why_asked": "正規化（単位ベクトルにそろえる操作）は、コサイン類似度の計算やニューラルネットワークの重みの初期化・正則化など、向きだけを比較したい場面で頻繁に使われる基礎操作。", "kid": "正規化（せいきか）は、あるベクトルの向きはそのままにして、長さ（ノルム、ベクトルの長さを測る値）だけをちょうど1に調整する操作のこと。もとのベクトルの各成分を、そのベクトルの長さで割ることで実現できる。こうしてできた、長さがちょうど1のベクトルを単位ベクトルと呼ぶ。", "eg": "たとえるなら、いろいろな長さの矢印が何本もあるとき、それぞれの矢印を同じ向きのまま、長さだけ1メートルにそろえるイメージ。長さをそろえることで、矢印同士の『向きの違い』だけを公平に比べられるようになる。", "terms": [["正規化（normalization）", "ベクトルの向きを変えずに、長さ（ノルム）を1に調整する操作。各成分をベクトルの長さで割って計算する"], ["単位ベクトル", "正規化によってできる、長さがちょうど1のベクトル"], ["ノルム", "ベクトルの長さ（大きさ）を表す値。成分を2乗して足し、その結果を掛けるともとに戻る数に戻すことで求められる"]], "think": "正規化は『各成分をベクトルの長さ（ノルム）で割る』という1つの操作でできる。ベクトルの各成分を同じ数（そのベクトル自身の長さ）で割ると、向き（各成分の比率）は変わらないまま、全体の長さだけがちょうど1に縮む。これが向きを保ったまま長さだけ1にそろえられる理由。", "calc": {"steps": ["問題: 成分が3と4のベクトル(3,4)を正規化し、単位ベクトルを求める", "ステップ1: まずベクトルの長さ（ノルム）を求める。各成分を2乗して足す。3×3+4×4=9+16=25", "ステップ2: 25を、掛けると25になる数に戻す。5×5=25なので、長さは5", "ステップ3: 各成分を、求めた長さ5で割る。3÷5=0.6、4÷5=0.8", "答え: 単位ベクトルは(0.6, 0.8)。向きは(3,4)と同じで、長さはちょうど1になっている"], "formula": "単位ベクトル = (3,4) ÷ 長さ(3,4) = (3,4) ÷ 5 = (0.6, 0.8)"}, "vs": "転置は行と列を入れ替えるだけの操作でベクトルの長さは変わらず、内積は2つのベクトルから1つの数値を作る計算であって、長さを1にそろえる正規化とは目的も結果も異なる。", "opt": ["正解。正規化と呼び、できたベクトルは単位ベクトルと呼ばれる。向きは変えずに長さだけを1にそろえる操作。", "転置は行と列を入れ替える操作で、できあがるのは基底ベクトルではなく、単に並びが変わることもある元のベクトルにすぎない。", "内積は2つのベクトルから1つの数値（スカラー）を作る計算であり、長さが0のゼロベクトルを作る操作でもないため、この説明には当てはまらない。", "射影はあるベクトルを別の方向に投影する操作で、できるベクトルは長さが1とは限らず、固有ベクトルになるとも限らない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30\" y1=\"120\" x2=\"330\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"60\" y1=\"130\" x2=\"60\" y2=\"20\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"60\" y1=\"120\" x2=\"150\" y2=\"40\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"155\" y=\"40\" font-size=\"9\" fill=\"#8892a4\">元のベクトル（長さ5）</text><line x1=\"60\" y1=\"120\" x2=\"96\" y2=\"94\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"60\" y=\"105\" font-size=\"9\" fill=\"#60a5fa\">正規化後（長さ1）</text></svg>"}'),

  ('g-kentei-k-q43', '8. AIに必要な数理・統計知識',
   '同じ形をした2つの行列（またはベクトル）について、対応する位置の成分同士をそのまま掛け合わせ、同じ形の結果を作る演算を何と呼ぶか。LSTMなどのゲート機構で使われている。',
   NULL::text,
   '["アダマール積（要素ごとの積のこと）", "内積（ドット積のこと）", "外積（ベクトル積のこと）", "行列積（一般の掛け算のこと）"]',
   0, '[0]', 'single',
   '{"asked": "同じ形の行列・ベクトル同士で、対応する成分をそのまま掛け合わせる演算の名前を問う問題。", "why_asked": "アダマール積はLSTMのゲート機構（情報をどれだけ通すかを0〜1の値で成分ごとに調整する仕組み）などで使われており、内積・行列の積との違いを理解しているかが問われる。", "kid": "アダマール積（アダマールせき）は、同じ形をした2つの行列やベクトルについて、同じ位置にある成分同士をそのまま掛け算して、もとと同じ形の結果を作る演算のこと。たとえばベクトル(2,3)とベクトル(4,5)のアダマール積は、2×4と3×5をそれぞれ計算した(8,15)になる。1つの数値にまとめる内積とは違い、結果もベクトルや行列のまま残る。", "eg": "たとえるなら、2つの成績表があって、同じ科目同士の点数をそれぞれ掛け合わせて、科目ごとの新しい表を作るようなもの。1つの合計点にまとめるわけではなく、科目という『形』はそのまま保たれる。これがアダマール積のイメージ。", "terms": [["アダマール積（Hadamard product）", "同じ形の行列・ベクトル同士で、対応する成分をそのまま掛け合わせる演算。結果も同じ形のまま"], ["ゲート機構", "LSTMなどで、情報をどれだけ通すかを0〜1の値で成分ごとに調整する仕組み。アダマール積で実現される"], ["内積（ドット積）", "2つのベクトルの対応する成分を掛けて、その総和を1つの数値にまとめる演算。アダマール積とは結果の形が異なる"]], "think": "アダマール積は『同じ位置の成分同士を掛けるだけ』で、足し合わせて1つの数値にまとめる操作を行わない。だから結果も入力と同じ形の行列・ベクトルのまま残る。LSTMのゲート機構では、0〜1の値を持つゲートベクトルと、情報を表すベクトルをアダマール積で掛け合わせることで、成分ごとに『どれだけ通すか』を個別に調整できる。これは1つの数値にまとめてしまう内積ではできない使い方。", "vs": "内積は対応する成分を掛けたあとに全部足し合わせて1つの数値にする演算で、結果が同じ形のまま残るアダマール積とは結果の種類が根本的に異なる。行列の積（一般的な掛け算）は行と列の組み合わせごとに内積を繰り返す演算で、形の条件も異なる別の演算。", "opt": ["正解。同じ形の行列・ベクトル同士で、対応する成分をそのまま掛け合わせる演算。結果も同じ形のまま残る。", "内積は対応する成分を掛けたあとに全部足し合わせて1つの数値にする演算で、結果が行列・ベクトルの形のまま残るアダマール積とは異なる。", "外積は主に3次元ベクトル同士から新しいベクトルを作る演算で、同じ形の行列同士の成分ごとの掛け算とは計算のしかたが異なる。", "一般的な行列の積は、前の行列の列数と後ろの行列の行数が一致している必要があり、同じ形どうしでなくても計算できる点がアダマール積と異なる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"35\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1\"/><text x=\"30\" y=\"55\" font-size=\"10\" fill=\"#e8eaf0\">2</text><rect x=\"20\" y=\"75\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1\"/><text x=\"30\" y=\"95\" font-size=\"10\" fill=\"#e8eaf0\">3</text><text x=\"60\" y=\"70\" font-size=\"12\" fill=\"#8892a4\">⊙</text><rect x=\"90\" y=\"35\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1\"/><text x=\"100\" y=\"55\" font-size=\"10\" fill=\"#e8eaf0\">4</text><rect x=\"90\" y=\"75\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1\"/><text x=\"100\" y=\"95\" font-size=\"10\" fill=\"#e8eaf0\">5</text><text x=\"130\" y=\"70\" font-size=\"12\" fill=\"#8892a4\">=</text><rect x=\"160\" y=\"35\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"168\" y=\"55\" font-size=\"10\" fill=\"#60a5fa\">8</text><rect x=\"160\" y=\"75\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"166\" y=\"95\" font-size=\"10\" fill=\"#60a5fa\">15</text><text x=\"200\" y=\"55\" font-size=\"9\" fill=\"#8892a4\">同じ位置同士を掛けるだけ</text><text x=\"200\" y=\"70\" font-size=\"9\" fill=\"#8892a4\">（足し合わせない、形も保たれる）</text></svg>"}'),

  ('g-kentei-k-q44', '8. AIに必要な数理・統計知識',
   'ある工場から製品を5個抜き取って重さのばらつき(分散)を調べ、そこから工場全体(母集団)の分散を推定したい。このとき、5個のデータから計算した「平均との差を2乗して全部足したもの」を、5ではなく4(5から1を引いた数)で割る工夫をするのはなぜか。',
   NULL::text,
   '["標本の平均に対して測った差は小さめに出る癖があり、割る数を個体数そのものではなく1つ少ない数にすることで、その癖を埋め合わせているから。", "標本の数が少ないときに計算を簡単にするための昔からの慣習で、標本の個体数が十分に多くなれば、割る数を1つ減らしても減らさなくてもほとんど差が出ないから。", "測定ミスや欠損など、思いがけないデータが混ざってしまう可能性をあらかじめ見込んで、個体の数を1つ多く見積もっておくための安全策だから。", "母集団の中には標本として抜き取られなかったデータが必ず1つ以上残っているはずなので、その分を割る数にあらかじめ反映させて調整しているから。"]',
   0, '[0]', 'single',
   '{"asked": "標本から母集団の分散を推定するとき、標本の個体数ではなく、そこから1つ少ない数で割る理由を問う問題。", "why_asked": "「分散は平均との差を2乗したものの平均」という基本の式をそのまま標本に当てはめると、気づかないうちに母集団の分散を小さく見積もってしまう、という統計の定番の落とし穴。", "kid": "標本(全体の中から抜き取った一部のデータ)の平均は、たまたま抜き取った数個のちょうど真ん中あたりの値になる。だから標本の中だけで「平均との差」を測ると、その平均自身に対して測っているぶん、差が本来より小さめに出てしまう。そこで、割る数を標本の個体数(n、標本に入っているデータの個数)ではなく、1つ少ない数(n-1)にすることで、小さく出た分を埋め合わせて、母集団(全体)の本当の散らばり具合に近づけている。", "eg": "たとえるなら、クラスの中だけで「クラス平均からのズレ」を測ると、そのクラス自身の平均に対して測っているぶん、ズレは実際より小さめに出やすい。学校全体(母集団)の平均から測ったズレの方が本当は大きいはずなので、割る数を1つ減らして帳尻を合わせている、というイメージ。", "terms": [["母集団", "本当に知りたい全体のデータの集まり"], ["標本", "母集団の中から一部を抜き取ったデータ"], ["不偏分散", "標本のデータから、1つ少ない数で割って計算し、母集団の分散に偏りなく近づけた分散"]], "think": "標本の平均は、その標本のデータたちにとって一番近い場所に来るように計算された値なので、標本の中だけで測った「平均との差」はどうしても小さめに出やすい。この小さめに出る癖(偏り)をそのまま残すと、せっかく計算した分散が母集団の本当の分散より小さく出てしまう。そこで割る数を1つ減らすことで、値全体を少し大きくして、小さめに出る癖を打ち消している。", "vs": "母集団そのものの分散を計算するとき(全データが手元にある場合)は、標本の個体数そのもので割ってよい。1つ少ない数で割るのは、あくまで一部のデータ(標本)から母集団の分散を推定するときだけ、という場面の違いに注意。", "opt": ["正解。標本の平均に対して測った差はどうしても小さめに出る癖があり、割る数を標本の個体数そのものではなく1つ少ない数にすることで、その小さめの癖を埋め合わせているから。", "標本の個体数が十分に多くなれば割る数の差の影響はほとんど無くなっていくが、これは1つ少ない数で割る理由そのものではなく、あくまで人数が多い場合の結果にすぎない。", "測定ミスや欠損への備えという安全マージンの発想であり、標本の平均が本来より小さめの散らばりを示してしまう偏りを補正する、という本来の理由とは異なる。", "抜き取られなかったデータの存在を割る数に反映させるという説明では、なぜ1つだけ引くのかという具体的な理由が示せておらず、実際の偏りの補正とは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">標本の点は、標本平均に一番近づくように並ぶ</text><line x1=\"20\" y1=\"80\" x2=\"320\" y2=\"80\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"60\" y1=\"65\" x2=\"60\" y2=\"95\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"60\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">母平均</text><circle cx=\"190\" cy=\"80\" r=\"4\" fill=\"#e8eaf0\"/><circle cx=\"210\" cy=\"80\" r=\"4\" fill=\"#e8eaf0\"/><circle cx=\"230\" cy=\"80\" r=\"4\" fill=\"#e8eaf0\"/><circle cx=\"250\" cy=\"80\" r=\"4\" fill=\"#e8eaf0\"/><line x1=\"220\" y1=\"60\" x2=\"220\" y2=\"100\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"220\" y=\"117\" text-anchor=\"middle\" font-size=\"9\" fill=\"#3b82f6\">標本平均</text><text x=\"220\" y=\"132\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">点からの差は小さく出やすい</text></svg>"}'),

  ('g-kentei-k-q45', '8. AIに必要な数理・統計知識',
   'サイコロの出目のように偏った分布(母集団)からでも、標本(例えば100個ずつ)を何度も取り、その標本ごとの平均を計算して集めていくと、その標本平均たちの分布の形はどうなっていくか。',
   NULL::text,
   '["母集団の分布の形が何であっても、標本平均たちを集めた分布の形は、山が真ん中に1つだけある釣鐘型(正規分布)に近づいていく。", "標本平均たちも、元の母集団の分布と同じ形(サイコロなら平ら)に近づいていき、母集団の形の影響からは逃れられない。", "標本の個体数を増やすほど、標本平均という値そのものが母平均にぴったり一致するようになり、分布という考え方自体が不要になる。", "標本平均たちを集めた分布は、標本を取るたびに形が変わり続け、特定の形に近づくことはなく予測できない。"]',
   0, '[0]', 'single',
   '{"asked": "母集団の分布の形によらず、標本平均を何度も計算して集めた分布が正規分布に近づいていく、という性質(中心極限定理)を問う問題。", "why_asked": "既出の大数の法則(値そのものが母平均に近づく)と名前も内容も混同されやすく、「何が正規分布に近づくのか」を区別できるかを問う定番の論点。", "kid": "サイコロの出目は1から6が同じ確率で出る、四角い(平らな)形の分布。1回振っただけの結果を集めても四角い形のままだが、「100回振って平均を取る」という作業を何度も繰り返し、その「100回の平均」をたくさん集めて分布を作ると、元がどんな形の母集団であっても、真ん中が高く両端が低い釣鐘型(正規分布)の形に近づいていく。", "eg": "たとえるなら、クラス全員(母集団)の身長がどんな形に散らばっていても、40人ずつのグループを何度も作って、それぞれのグループの平均身長を計算し、その平均身長たちを集めてヒストグラムにすると、グループの平均身長は釣鐘型に集まってくる、というイメージ。個々の身長がどんな形でも、平均という「まとめる作業」を挟むと形が整う。", "terms": [["中心極限定理", "母集団の分布の形によらず、標本平均を集めた分布が正規分布に近づいていく性質"], ["標本平均", "一部のデータ(標本)から計算した平均"], ["正規分布", "真ん中が一番高く、両端に向かってなだらかに低くなる釣鐘型の分布"]], "think": "この性質のポイントは「近づいていく先」が2つある、ということ。大数の法則は「標本平均という値そのもの」が母平均に近づいていくという話だったが、中心極限定理は「標本平均を何度も計算して集めたときの、その集まり(分布)の形」が正規分布に近づいていくという話。値が近づくのか、分布の形が近づくのか、という着眼点の違いを押さえる。", "vs": "大数の法則(既出)と混同しやすい。大数の法則は標本平均という値そのものが母平均に近づいていく性質、中心極限定理は標本平均を集めた分布の形が正規分布に近づいていく性質で、指しているものが違う。", "opt": ["正解。母集団の分布の形が何であっても、標本平均たちを集めた分布の形は正規分布(釣鐘型)に近づいていく。", "標本平均を集めた分布は元の母集団の分布の形に引きずられるという考え方だが、実際には母集団の形によらず正規分布に近づいていく点が中心極限定理の特徴。", "標本平均という値そのものが母平均に近づいていく性質は大数の法則の内容であり、標本平均を集めた分布の形が正規分布に近づく中心極限定理とは着眼点が異なる。", "標本の個体数を十分に増やせば、標本平均を集めた分布の形は正規分布という決まった形に近づいていくため、形が予測できないというのは実際とは逆になる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"70\" y=\"16\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">母集団の分布(どんな形でも)</text><rect x=\"20\" y=\"70\" width=\"14\" height=\"40\" fill=\"#e8eaf0\"/><rect x=\"38\" y=\"50\" width=\"14\" height=\"60\" fill=\"#e8eaf0\"/><rect x=\"56\" y=\"90\" width=\"14\" height=\"20\" fill=\"#e8eaf0\"/><rect x=\"74\" y=\"40\" width=\"14\" height=\"70\" fill=\"#e8eaf0\"/><rect x=\"92\" y=\"80\" width=\"14\" height=\"30\" fill=\"#e8eaf0\"/><line x1=\"10\" y1=\"110\" x2=\"120\" y2=\"110\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"85\" text-anchor=\"middle\" font-size=\"16\" fill=\"#8892a4\">→</text><text x=\"170\" y=\"100\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">標本平均を</text><text x=\"170\" y=\"111\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">何度も集める</text><text x=\"265\" y=\"16\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">標本平均を集めた分布</text><path d=\"M 210 110 Q 240 40 265 40 Q 290 40 320 110\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"210\" y1=\"110\" x2=\"320\" y2=\"110\" stroke=\"#2a2f3f\"/><text x=\"265\" y=\"128\" text-anchor=\"middle\" font-size=\"9\" fill=\"#3b82f6\">正規分布(釣鐘型)</text></svg>"}'),

  ('g-kentei-k-q46', '8. AIに必要な数理・統計知識',
   '同じ母集団から100人ずつ標本を取り、その標本平均を計算する、という作業を何度も繰り返した。このとき、標本の人数を100人から400人に増やすと、標本平均のばらつきの大きさ(標準誤差)はどうなるか。',
   NULL::text,
   '["標本の人数を増やすほど標準誤差は小さくなり、標本平均が母平均のまわりに安定して集まるようになる。", "標本の人数を増やしても標準誤差の大きさは変わらず、標本平均のばらつきは常に一定である。", "標本の人数を増やすほど標準誤差は大きくなり、標本平均のばらつきはむしろ広がっていく。", "標本の人数を増やすと、標準誤差ではなく母集団そのもののばらつき(標準偏差)のほうが小さくなっていく。"]',
   0, '[0]', 'single',
   '{"asked": "標本の個体数を増やすと、標本平均のばらつきの大きさを表す標準誤差がどう変化するかを問う問題。", "why_asked": "標準偏差(1つ1つのデータのばらつき)と標準誤差(標本平均のばらつき)を混同しやすく、「何のばらつきを指しているか」を区別できるかを問う論点。", "kid": "標準誤差は、標本平均という値が、標本を取り直すたびにどれくらいブレるかを表す数字。標本の人数を増やすと、1つの標本の中にいろいろな人が混ざって平均が均される(平らにならされる)ので、標本を取り直すたびの平均のブレ幅がだんだん小さくなっていく。つまり、標本の人数を増やすほど、標準誤差は小さくなる。", "eg": "たとえるなら、クラスから3人だけ抜き出して平均身長を測ると、たまたま背の高い3人が選ばれて平均が大きくブレることがある。でも30人抜き出せば、高い人も低い人も混ざるので、平均はブレにくくなる。この「抜き出す人数を増やすとブレにくくなる」度合いが標準誤差。", "terms": [["標準誤差", "標本平均が、標本を取り直すたびにどれくらいブレるかを表す値"], ["標準偏差", "1つ1つのデータが平均からどれくらい離れているかを表す値"]], "calc": {"steps": ["問題: 標準偏差が20のとき、標本の人数を100人から400人に増やすと標準誤差はどう変わるか", "ステップ1: 人数100人のときの標準誤差を求める。100の√(ルート、2乗すると元の数に戻る数)は10(10×10=100だから)。20 ÷ 10 = 2", "ステップ2: 人数400人のときの標準誤差を求める。400の√は20(20×20=400だから)。20 ÷ 20 = 1", "答え: 人数を100人から400人(4倍)に増やすと、標準誤差は2から1へと半分になる"], "formula": "標準誤差 = 標準偏差 ÷ √n（nは標本の人数、√は「2乗すると元の数に戻る数」を求める計算）"}, "think": "標準偏差は「1人1人のデータが平均からどれだけ離れているか」を表す値で、標本の人数を増やしても小さくはならない(バラつきの元の大きさは変わらないから)。それに対して標準誤差は「標本平均という、たくさんのデータをまとめた値」のブレ幅なので、まとめる人数が増えるほど個々のブレが打ち消し合って平均は安定し、標準誤差は小さくなっていく。", "vs": "標準偏差(個々のデータのばらつき)と標準誤差(標本平均のばらつき)は名前が似ているが指しているものが違う。標本の人数を増やしても標準偏差そのものはほとんど変わらないが、標準誤差は小さくなっていく。", "opt": ["正解。標本の人数を増やすほど標準誤差は小さくなり、標本平均が母平均のまわりに安定して集まるようになる。", "標準偏差(個々のデータのばらつき)であれば人数を増やしても大きくは変わらないが、標本平均のばらつきである標準誤差は人数を増やすほど小さくなっていく。", "標本の人数を増やすと混ざるデータの種類が増えて逆にばらつくという考え方だが、実際には人数を増やすほど平均は安定し、標準誤差は小さくなる。", "母集団そのものの標準偏差は標本の人数を増やしても基本的には変わらず、人数の影響を受けて小さくなっていくのは標本平均のばらつきである標準誤差の方。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">標本の人数(n)を増やすと、分布は締まっていく</text><line x1=\"30\" y1=\"115\" x2=\"310\" y2=\"115\" stroke=\"#2a2f3f\"/><path d=\"M 60 115 Q 170 30 280 115\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/><text x=\"85\" y=\"100\" font-size=\"9\" fill=\"#c47070\">人数100(広い)</text><path d=\"M 120 115 Q 170 55 220 115\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"215\" y=\"70\" font-size=\"9\" fill=\"#3b82f6\">人数400(狭い)</text></svg>"}'),

  ('g-kentei-k-q47', '8. AIに必要な数理・統計知識',
   '新しい教え方をしたクラスと、いつも通りの教え方をしたクラスで、テストの平均点に差が出るかどうかを調べたい。このとき「新しい教え方と普段の教え方で、テストの平均点に差はない」とまず仮に立てておき、それを否定できるかどうかで判断する、という進め方を何と呼ぶか。',
   NULL::text,
   '["仮説検定(帰無仮説を立てて、それを否定できるかどうかで判断するやり方)", "回帰分析(2つの数値の関係を1本の直線の式で表し、そこから予測するやり方)", "信頼区間の推定(本当の値がある範囲に入っていると一定の自信度で言うやり方)", "ベイズ更新(新しい証拠が出るたびに確率を計算し直していくやり方)"]',
   0, '[0]', 'single',
   '{"asked": "「差はない」という仮説をまず立てて、それを否定できるかどうかで判断する進め方(仮説検定)の名前と考え方を問う問題。", "why_asked": "仮説検定は統計的な判断の土台になる考え方で、この後に出てくるp値・有意水準・信頼区間もすべてこの枠組みの上に乗っているため、まずこの構造そのものを理解できているかを問う定番の論点。", "kid": "仮説検定は、いきなり「差がある」と言い切るのではなく、まず「差はない」という仮の立場(帰無仮説。読み方はきむかせつ。否定されるために立てる仮の説)に立ってみて、実際のデータがその仮の立場と矛盾していないかを確かめるやり方。データが「差はない」という仮の立場ではとても起こりにくいものだった場合に、はじめて「差はないとは考えにくい、だから差があると考えよう」という結論(対立仮説。読み方はたいりつかせつ。本当に言いたい方の説)に進む。", "eg": "たとえるなら裁判の「推定無罪」に似ている。裁判ではまず被告を「無罪(何もしていない)」という仮の立場に立たせ、検察が「無罪だとしたらこの証拠は説明がつかない」という強い証拠を出せたときだけ、有罪だと判断する。仮説検定も同じで、まず「差はない」という無罪の立場に立ち、データがその立場では説明がつかないくらい極端だったときだけ「差がある」と判断する。", "terms": [["帰無仮説", "否定されることを狙って立てる、まず仮に立てる「差はない・効果はない」という仮の説"], ["対立仮説", "帰無仮説が否定されたときに採用する、本当に言いたい方の説"], ["仮説検定", "帰無仮説を立て、それを否定できるかどうかでデータを判断するやり方"]], "think": "仮説検定の背骨は「いきなり言いたいことを証明しようとしない」という順番にある。「差がある」ことを直接証明するのは難しいが、「差はない」という仮の立場に立って、そこから予想されるデータの起こりやすさを計算するのは可能。実際のデータがその仮の立場ではめったに起こらないくらい極端だったときに、はじめて仮の立場(帰無仮説)を退け、本当に言いたい方(対立仮説)を採用する、という間接的な進め方をとる。", "vs": "信頼区間の推定は「本当の値がどの範囲にあるか」を幅で言い当てるやり方で、仮説検定とは目的が違う(ただし裏では同じ計算を使うことが多い)。ベイズ更新は新しい証拠のたびに確率そのものを計算し直すやり方で、「差はない」という仮の立場を立てて否定を狙う仮説検定の進め方とは考え方の出発点が異なる。", "opt": ["正解。「差はない・効果はない」という仮説(帰無仮説)をまず立てて、それを否定できるかどうかでデータを判断するやり方。", "2つの数値の関係を1本の直線の式で表し、そこから予測するやり方で、「差はない」という仮の立場を立てて否定を狙う進め方とは目的が異なる。", "本当の値がある範囲に入っていると一定の自信度で言うやり方で、幅を持たせた推定が目的であり、仮の立場を否定するかどうかで判断する進め方とは異なる。", "新しい証拠が出るたびに確率を計算し直していくやり方で、まず「差はない」という仮説を立てて否定を狙う進め方とは考え方の出発点が異なる。"]}'),

  ('g-kentei-k-q48', '8. AIに必要な数理・統計知識',
   'ある薬を使った患者グループと使わなかった患者グループの回復率を比べたところ、p値(読み方はピーち)が0.02だった。有意水準を5%(0.05)に設定していた場合、この結果からどう判断するのが妥当か。',
   NULL::text,
   '["p値(0.02)が有意水準(0.05)より小さいので、この結果は偶然とは考えにくく、薬に効果があると判断する。", "p値(0.02)は薬の効果そのものの大きさを表す数値なので、薬には2%程度のわずかな効果しかないと判断する。", "p値(0.02)が有意水準(0.05)より小さいので、薬に効果がある確率は98%だと判断する。", "p値と有意水準はどちらも研究者が自由に決めてよい数値なので、この2つを比べるだけでは薬の効果について何も判断できない。"]',
   0, '[0]', 'single',
   '{"asked": "p値と有意水準を比べて、薬に効果があると判断してよいかどうかを問う問題。", "why_asked": "p値を「効果の大きさ」や「効果がある確率」だと誤解する人が非常に多く、p値の正しい意味(帰無仮説のもとでこのデータが偶然起こる確率)を理解できているかを問う定番の論点。", "kid": "p値は、「薬に効果がない」という仮の立場(帰無仮説)が正しいとしたら、今回のような結果(またはそれ以上に差が大きい結果)が偶然に起きる確率のこと。有意水準は、「この確率より小さかったら、もう偶然とは考えにくい」と判断する境目のライン(よく5%が使われる)。p値が有意水準より小さければ、「効果がないという仮の立場では、こんな結果はめったに起きないはずなのに実際に起きた、だから効果がないとは考えにくい」と判断する。", "eg": "たとえるなら、コインを10回投げて10回とも表が出たとする。「このコインは普通のコイン(裏表五分五分)」という仮の立場に立つと、10回連続で表になる確率はとても低い(p値がとても小さい)。だから「このコインは普通のコインではない(何か仕掛けがある)」と判断する。p値が小さいというのは、仮の立場ではめったに起きないことが実際に起きた、というサイン。", "terms": [["p値", "帰無仮説(差がない・効果がないという仮の立場)が正しいとしたら、今回のデータが偶然起こる確率"], ["有意水準", "p値がこれより小さければ「偶然とは考えにくい」と判断する境目のライン。よく5%が使われる"]], "think": "p値(0.02)と有意水準(0.05)を比べると、p値の方が小さい。これは「薬に効果がない」という仮の立場に立ったとき、今回のような回復率の差が偶然起こる確率がわずか2%しかない、ということを意味する。あらかじめ「5%より低かったら偶然とは考えにくいと判断しよう」と決めていたので、この結果は仮の立場(効果がない)を否定する材料になり、「薬に効果がある」と判断する。", "vs": "p値を「薬の効果そのものの大きさ」や「効果がある確率」だと読み違えるのは非常によくある誤解。p値はあくまで「効果がないという仮の立場のもとで、このデータが偶然起こる確率」であり、効果の大きさや、効果がある確率そのものを直接表す数値ではない。", "opt": ["正解。p値(0.02)が有意水準(0.05)より小さいので、「効果がない」という仮の立場ではこの結果は偶然とは考えにくく、効果があると判断する。", "p値は「効果がない」という仮の立場のもとでこのデータが偶然起こる確率を表す数値であり、薬の効果そのものの大きさを表す数値ではない。", "p値は「効果がない」という仮の立場のもとでこのデータが偶然起こる確率であり、その値をそのまま1から引いて「効果がある確率」と読み替えることはできない。", "有意水準はあらかじめ研究者が決める境目のラインだが、p値と比べることで「偶然とは考えにくいか」を判断できるため、何も判断できないというのは実際とは異なる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">「効果はない」という仮の立場での結果の分布</text><line x1=\"20\" y1=\"110\" x2=\"320\" y2=\"110\" stroke=\"#2a2f3f\"/><path d=\"M 30 110 Q 170 20 310 110\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><path d=\"M 260 110 Q 285 70 310 110 Z\" fill=\"#c47070\" opacity=\"0.5\"/><line x1=\"260\" y1=\"30\" x2=\"260\" y2=\"115\" stroke=\"#c9a04a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"260\" y=\"128\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">有意水準の境目</text><text x=\"293\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">p値</text><text x=\"150\" y=\"55\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">よく起こる範囲</text></svg>"}'),

  ('g-kentei-k-q49', '8. AIに必要な数理・統計知識',
   'ある町の成人の平均身長を調べるため、100人を標本として抽出し、平均身長を計算した。その結果をもとに「本当の平均身長(母平均)は165cmから169cmの間にある」と、95%の自信度で述べた。この165cmから169cmという幅のことを何と呼ぶか。',
   NULL::text,
   '["信頼区間(本当の値がこの範囲にあると、一定の自信度をつけて言える範囲のこと)", "有意水準(偶然とは考えにくいと判断するときに使う、あらかじめ決めておく境目のライン)", "標準誤差(標本を取り直すたびに、標本平均がどれくらいブレるかを表す1つの数値)", "四分位範囲(データを大きさ順に並べて4等分したときの、真ん中50%が収まる範囲)"]',
   0, '[0]', 'single',
   '{"asked": "「本当の値はこの範囲にある」と一定の自信度で述べるときの、その幅のことを何と呼ぶかを問う問題。", "why_asked": "点(1つの値)で言い当てようとする点推定と、幅を持たせて言う区間推定の違い、そして信頼区間という名前とその意味を対応づけられるかを問う定番の論点。", "kid": "標本から計算した平均(165cmと169cmの真ん中あたり)は、あくまで一部の人だけを測った結果なので、本当の平均(母平均)とぴったり一致するとは限らない。そこで「ピンポイントでここ」と言い切る代わりに、「だいたいこの範囲のどこかにあるはず」と幅を持たせて言う。この幅のことを信頼区間と呼び、「95%の自信度で」というのは、同じやり方で何度も標本を取って区間を作ったら、そのうち95%くらいはちゃんと本当の値を含んでいるはずだ、という意味合い。", "eg": "たとえるなら、暗い部屋で物を探すとき、「ここに置いてあります」とピンポイントで言うより、「このあたりの1畳分の範囲のどこかにあります」と幅を持たせて言った方が、外れにくく実用的。信頼区間もこれと同じで、1点で言い当てる代わりに、当たる可能性が高い範囲を示している。", "terms": [["信頼区間", "本当の値(母平均など)がこの範囲にある、と一定の自信度で言える範囲"], ["点推定", "標本から計算した1つの値(例えば標本平均そのもの)で本当の値を言い当てるやり方"], ["区間推定", "1点ではなく幅を持たせて本当の値を言い当てるやり方。信頼区間はこのやり方の結果"]], "think": "標本平均のような1つの値だけで「本当の平均はこれです」と言い切る(点推定)のは、標本を取り直すたびに値がブレる(標準誤差がある)ことを考えると言い過ぎになりやすい。そこで、そのブレの大きさを考慮して「このくらいの幅の中には、まず本当の値が入っているはずだ」という言い方に変えたのが信頼区間で、区間推定という考え方にあたる。", "vs": "有意水準は「偶然とは考えにくい」と判断する境目のラインで、仮説検定の場面で使う言葉。信頼区間は「本当の値がどこにあるか」を幅で推定する場面で使う言葉で、目的も出てくる場面も異なる(ただし裏側の計算はつながっている)。", "opt": ["正解。本当の値(母平均など)がこの範囲にある、と一定の自信度をつけて言える範囲のことを信頼区間と呼ぶ。", "偶然とは考えにくいと判断するときに使う、あらかじめ決めておく境目のラインのことで、仮説検定の場面で使う言葉であり、本当の値がある範囲を示す言葉ではない。", "標本を取り直すたびに標本平均がどれくらいブレるかを表す1つの数値のことで、幅を持たせて本当の値の在りかを示す信頼区間とは、1つの数値か範囲かという点で異なる。", "データを大きさ順に並べて4等分したときの、真ん中50%が収まる範囲のことで、本当の値の在りかを自信度つきで示す信頼区間とは目的が異なる。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">1点で言い切る代わりに、幅で「このあたり」と言う</text><line x1=\"30\" y1=\"70\" x2=\"310\" y2=\"70\" stroke=\"#2a2f3f\"/><line x1=\"140\" y1=\"70\" x2=\"220\" y2=\"70\" stroke=\"#3b82f6\" stroke-width=\"4\"/><line x1=\"140\" y1=\"60\" x2=\"140\" y2=\"80\" stroke=\"#3b82f6\" stroke-width=\"2\"/><line x1=\"220\" y1=\"60\" x2=\"220\" y2=\"80\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"140\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#3b82f6\">165cm</text><text x=\"220\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#3b82f6\">169cm</text><text x=\"180\" y=\"50\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">信頼区間(95%)</text><circle cx=\"180\" cy=\"70\" r=\"3\" fill=\"#c9a04a\"/><text x=\"180\" y=\"116\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">この中に本当の平均がある、と95%の自信度で言う</text></svg>"}'),

  ('g-kentei-k-q50', '8. AIに必要な数理・統計知識',
   '以前の問題(病気の検査)で計算したベイズの定理を、言葉で整理し直す。検査を受ける前の「病気にかかっている人はもともと1%」という確率、検査結果が出た後の「陽性と分かった上で病気である確率(約8%)」、「病気だとしたら陽性になりやすい度合い(90%)」の3つを、それぞれ何と呼ぶか。',
   NULL::text,
   '["「もともと1%」が事前確率、「陽性になりやすい度合い90%」が尤度、「陽性と分かった上での8%」が事後確率", "「もともと1%」が事後確率、「陽性になりやすい度合い90%」が尤度、「陽性と分かった上での8%」が事前確率", "「もともと1%」が事前確率、「陽性になりやすい度合い90%」が事後確率、「陽性と分かった上での8%」が尤度", "「もともと1%」が尤度、「陽性になりやすい度合い90%」が事前確率、「陽性と分かった上での8%」が事後確率"]',
   0, '[0]', 'single',
   '{"asked": "ベイズの定理を構成する3つの言葉(事前確率・尤度・事後確率)を、以前計算した病気の検査の場面に対応づける問題。", "why_asked": "ベイズの定理は計算そのものより、事前確率・尤度・事後確率という3つの言葉が「どの数字を指しているか」を混同することの方が実務でも多く、言葉の対応づけを問う定番の論点。", "kid": "事前確率は、証拠(検査結果)を見る前からもともと分かっている確率のこと(病気の人はもともと1%)。尤度(読み方はゆうど)は、あるパラメータ(病気にかかっているという状態)のもとで、そのデータ(陽性という検査結果)がどれくらい起きやすいかという度合いのこと(病気の人が陽性になる確率90%)。事後確率は、証拠(検査結果)を見た後に、事前確率を更新して出てきた確率のこと(陽性と分かった上で本当に病気である確率、約8%)。", "eg": "たとえるなら、犯人捜しで最初に疑わしい人を10人に絞る(事前確率)。次に「この人が犯人だとしたら、この目撃証言が出てくるのはどれくらいありそうか」を1人ずつ考える(尤度)。そして目撃証言(証拠)を踏まえて、10人それぞれが犯人である確率を計算し直す(事後確率)、という3段階の流れ。", "terms": [["事前確率", "証拠を見る前の、もともとの確率"], ["尤度", "あるパラメータ(状態)のもとで、そのデータが起きやすい度合い"], ["事後確率", "証拠を見た後に、事前確率を更新して出てきた確率"]], "think": "3つの言葉は、証拠を見る前・証拠が起きやすいかどうか・証拠を見た後、という時間の流れと役割で区別する。「もともと1%」は証拠(検査結果)より前の情報なので事前確率。「病気だとしたら陽性になりやすい度合い90%」は、病気という状態を前提としたときにデータ(陽性)が起きる度合いなので尤度。「陽性と分かった上での8%」は、証拠を踏まえて更新された後の確率なので事後確率、という対応になる。", "vs": "尤度(病気だとしたら陽性になりやすい度合い90%)と事後確率(陽性と分かった上で病気である確率8%)は、どちらも「病気」と「陽性」が出てくるが向きが逆。尤度は病気を前提にデータの起きやすさを見ており、事後確率はデータを前提に病気である確率を見ている。", "opt": ["正解。「もともと1%」が事前確率、「陽性になりやすい度合い90%」が尤度、「陽性と分かった上での8%」が事後確率という対応になる。", "証拠を見る前の確率が事前確率、証拠を見た後に更新された確率が事後確率なので、「もともと1%」を事後確率、「陽性と分かった上での8%」を事前確率とする対応は前後が逆になっている。", "「陽性になりやすい度合い90%」はある状態を前提にデータの起きやすさを見ている尤度であり、証拠を見た後に更新された事後確率(陽性と分かった上での8%)とは向きが異なる。", "「もともと1%」は証拠を見る前の確率なので事前確率にあたり、ある状態を前提にデータの起きやすさを見る尤度(陽性になりやすい度合い90%)とは役割が異なる。"], "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">証拠(尤度)を通って、確率が更新される</text><rect x=\"20\" y=\"45\" width=\"110\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"75\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">事前確率</text><text x=\"75\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">もともと1%</text><line x1=\"135\" y1=\"65\" x2=\"200\" y2=\"65\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"205,65 197,60 197,70\" fill=\"#c9a04a\"/><text x=\"170\" y=\"55\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">尤度(90%)</text><rect x=\"210\" y=\"45\" width=\"110\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"265\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">事後確率</text><text x=\"265\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" fill=\"#3b82f6\">陽性を踏まえ約8%</text></svg>"}'),

  ('g-kentei-k-q51', '8. AIに必要な数理・統計知識',
   '最尤推定(既出)では、データ全体が起きる確率を、1個1個のデータが起きる確率をすべて掛け算して計算する。ところが実際にコンピュータで計算するときは、掛け算のままではなく、確率に対数(読み方はログ)を取ってから足し算に直して計算することが多い。この工夫をする実務上の理由として最も適切なものはどれか。',
   NULL::text,
   '["確率を掛け算すると値がどんどん小さくなり、コンピュータの桁数を超えて0として扱われてしまうことがあるため、対数で足し算に変えて避けるから。", "対数を取ると確率の値そのものが底上げされて大きくなるため、病気の検査のようにもともと少ない事象でも、より正確な確率を計算できるようになるから。", "対数を取ることで掛け算の結果が四捨五入されにくくなり、コンピュータの内部で起きる計算誤差がすべて完全になくなってしまうから。", "対数を取ると足し算だった計算が掛け算に変わるため、データの個数が多いときほど計算にかかる時間を大きく短縮できるようになるから。"]',
   0, '[0]', 'single',
   '{"asked": "最尤推定で、確率の掛け算をそのまま計算せずに対数を取って足し算に直す実務上の理由を問う問題。", "why_asked": "既出の最尤推定の考え方を土台に、実際にコンピュータで計算するときに直面する「小さすぎる数」という実務的な壁と、その解決策(対数)を理解できているかを問う論点。", "kid": "確率は0から1の間の数(1%とか30%とか)。この1より小さい数を何十個も何百個も掛け算していくと、値はどんどん小さくなっていき、しまいにはコンピュータが扱える一番小さい桁数よりも小さくなって、0として扱われてしまうことがある(これをアンダーフローと呼ぶ)。そこで、確率に対数(掛け算を足し算に変換してくれる計算の仕組み)を取ってから計算すると、掛け算が足し算になり、小さくなりすぎて消えてしまう問題を避けられる。", "eg": "たとえるなら、0.5を10回掛けるととても小さい数になり、100回掛けるとほとんど0のような扱いになってしまう。対数を取ると、この「どんどん小さくなる掛け算」が「少しずつ足していくだけの足し算」に置き換わるので、値が消えてしまう心配がなくなり、コンピュータでも安定して扱える。", "terms": [["対数", "掛け算を足し算に変換してくれる計算の仕組み。データが増えても値が扱いやすい大きさのままになる"], ["アンダーフロー", "小さすぎる数がコンピュータの扱える桁数を超えて0として扱われてしまう現象"], ["対数尤度", "確率の掛け算(尤度)に対数を取って、足し算の形に直したもの"]], "think": "最尤推定はデータ1個1個が起きる確率を全部掛け算して、一番それらしい(尤もらしい)パラメータを探すやり方。ところがデータの個数が増えるほど、1より小さい数の掛け算がどんどん重なって値が極端に小さくなり、コンピュータの計算では0として扱われてしまう危険がある。対数を取ると掛け算が足し算に変わる(対数の性質)ため、データが増えても値が極端に小さくならず、計算が安定する。これが実務で対数尤度を使う理由。", "vs": "対数を取っても、確率の大小関係(どのパラメータが一番それらしいか)という結論は変わらない。「対数を取ると値そのものがより正確になる」というのは誤解で、対数はあくまで計算を安定させるための道具であり、精度を上げるためのものではない。", "opt": ["正解。確率同士をたくさん掛け算すると値がどんどん小さくなり、コンピュータが扱える桁数を超えて0として扱われてしまう(アンダーフロー)ことがあるため、対数を取って掛け算を足し算に変えることで、この問題を避けられる。", "対数を取っても確率の大小関係という結論は変わらないだけで、確率の値そのものがより正確になったり、少ない事象でも精度が上がったりするわけではない。", "対数を取っても計算機の中では依然として近似の計算が行われており、計算誤差がすべて完全になくなるわけではない。", "対数の性質は掛け算を足し算に変えるものであり、足し算が掛け算に変わるという説明は変換の向きが逆になっている。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">掛け算のままだと値が消えていく → 対数で足し算に</text><text x=\"20\" y=\"38\" font-size=\"8\" fill=\"#c47070\">掛け算(0.9×0.9×0.9×…): どんどん0に近づく</text><rect x=\"20\" y=\"46\" width=\"80\" height=\"10\" fill=\"#c47070\"/><rect x=\"20\" y=\"61\" width=\"40\" height=\"10\" fill=\"#c47070\"/><rect x=\"20\" y=\"76\" width=\"15\" height=\"10\" fill=\"#c47070\"/><rect x=\"20\" y=\"91\" width=\"4\" height=\"10\" fill=\"#c47070\"/><text x=\"190\" y=\"38\" font-size=\"8\" fill=\"#3b82f6\">対数の足し算: 一定の幅で減るだけ</text><rect x=\"190\" y=\"46\" width=\"60\" height=\"10\" fill=\"#3b82f6\"/><rect x=\"190\" y=\"61\" width=\"60\" height=\"10\" fill=\"#3b82f6\" opacity=\"0.8\"/><rect x=\"190\" y=\"76\" width=\"60\" height=\"10\" fill=\"#3b82f6\" opacity=\"0.6\"/><rect x=\"190\" y=\"91\" width=\"60\" height=\"10\" fill=\"#3b82f6\" opacity=\"0.4\"/></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
